'use strict';
(function executeClassicHomepageBundle(sources){
  const host=document.head||document.documentElement;
  for(const [asset,source] of sources){
    const script=document.createElement('script');
    script.dataset.kgBundleSource=asset;
    script.textContent=source;
    host.appendChild(script);
    script.remove();
  }
})([["src/37-subscription-plans.js","\"use strict\";\n\n/*\n * 学员订阅套餐与权益模型。\n *\n * 本文件只负责：套餐常量、套餐设置、价格/折扣派生、权益/用量文案。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionPlansModule = function(ctx={}){\n    const refresh = function(){\n      if(typeof ctx.decorateSubscriptionElements === \"function\") ctx.decorateSubscriptionElements();\n    };\n\n    const PLAN_ALIASES = {\n      free:\"free\",\n      free_student:\"free\",\n      trial:\"free\",\n      monthly:\"monthly\",\n      month:\"monthly\",\n      basic:\"monthly\",\n      basic_student:\"monthly\",\n      quarterly:\"quarterly\",\n      quarter:\"quarterly\",\n      quarter_year:\"quarterly\",\n      qtr:\"quarterly\",\n      season:\"quarterly\",\n      half_year:\"half_year\",\n      halfyear:\"half_year\",\n      half_yearly:\"half_year\",\n      halfyearly:\"half_year\",\n      half:\"half_year\",\n      pro:\"half_year\",\n      pro_student:\"half_year\",\n      lifetime:\"lifetime\",\n      life:\"lifetime\",\n      forever:\"lifetime\"\n    };\n\n    const PLAN_ORDER = [\"free\",\"monthly\",\"quarterly\",\"half_year\",\"lifetime\"];\n\n    const PLANS = {\n      free:{\n        id:\"free\",\n        enabled:true,\n        name:\"免费学员\",\n        shortName:\"免费\",\n        level:0,\n        billingCycle:\"free\",\n      durationDays:0,\n        paymentAmountFen:0,\n        priceText:\"¥0\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"长期有效\",\n        badgeText:\"体验\",\n        description:\"适合公开示例、轻量练习和体验核心流程。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          demoOnly:true,\n          allExamPapers:false\n        },\n        limits:{\n          dailyTraining:10,\n          recallMaps:1,\n          graphNodes:50,\n          recallNodes:30,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      monthly:{\n        id:\"monthly\",\n        enabled:true,\n        name:\"月度会员\",\n        shortName:\"月度\",\n        level:1,\n        billingCycle:\"monthly\",\n      durationDays:30,\n        paymentAmountFen:2900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"30 天\",\n        badgeText:\"灵活\",\n        description:\"适合短期备考、阶段性冲刺和低门槛体验完整学习能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true\n        },\n        limits:{\n          dailyTraining:80,\n          recallMaps:20,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      quarterly:{\n        id:\"quarterly\",\n        enabled:true,\n        name:\"季度会员\",\n        shortName:\"季度\",\n        level:2,\n        billingCycle:\"quarterly\",\n      durationDays:90,\n        paymentAmountFen:7900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"90 天\",\n        badgeText:\"进阶\",\n        description:\"适合一个阶段的系统备考，权益与半年会员保持一致，开放更完整的题库训练和深度回忆能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      half_year:{\n        id:\"half_year\",\n        enabled:true,\n        name:\"半年会员\",\n        shortName:\"半年\",\n        level:3,\n        billingCycle:\"half_year\",\n      durationDays:180,\n        paymentAmountFen:13900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"180 天\",\n        badgeText:\"推荐\",\n        recommended:true,\n        description:\"适合完整备考周期，开放更完整的题库训练和深度回忆能力。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      },\n      lifetime:{\n        id:\"lifetime\",\n        enabled:true,\n        name:\"终身会员\",\n        shortName:\"终身\",\n        level:4,\n        billingCycle:\"lifetime\",\n      durationDays:-1,\n        paymentAmountFen:39900,\n        priceText:\"待配置\",\n        originalPriceText:\"\",\n        discountPercent:\"\",\n        durationText:\"永久有效\",\n        badgeText:\"终身\",\n        description:\"适合长期学习和深度用户，包含当前高级学习能力并预留后续高级功能。\",\n        features:{\n          basicTraining:true,\n          basicRecall:true,\n          personalGraph:true,\n          standardQuestionBank:true,\n          allExamPapers:true,\n          learningPackageImport:true,\n          learningPackageExport:true,\n          advancedRecall:true,\n          analytics:true,\n          futureAdvanced:true\n        },\n        limits:{\n          dailyTraining:-1,\n          recallMaps:-1,\n          graphNodes:-1,\n          recallNodes:-1,\n          importPackages:-1,\n          exportPackages:-1\n        }\n      }\n    };\n\n    const FEATURE_LABELS = {\n      basicTraining:\"基础刷题\",\n      basicRecall:\"基础深度回忆\",\n      personalGraph:\"个人知识图谱\",\n      demoOnly:\"公开示例体验\",\n      standardQuestionBank:\"标准题库训练\",\n      allExamPapers:\"全部已发布试卷\",\n      learningPackageImport:\"学习包导入\",\n      learningPackageExport:\"学习包导出\",\n      advancedRecall:\"高级深度回忆\",\n      analytics:\"学习分析\",\n      futureAdvanced:\"后续高级功能\"\n    };\n\n    const LIMIT_LABELS = {\n      dailyTraining:\"每日训练\",\n      recallMaps:\"回忆图谱\",\n      graphNodes:\"图谱卡牌\",\n      recallNodes:\"深度回忆知识点\",\n      importPackages:\"学习包导入\",\n      exportPackages:\"学习包导出\"\n    };\n\n    function normalizePlanId(planId){\n      const raw=String(planId || \"free\").trim();\n      const lower=raw.toLowerCase();\n      return PLAN_ALIASES[lower] || (PLANS[raw] ? raw : \"free\");\n    }\n    function basePlanById(planId){\n      return PLANS[normalizePlanId(planId)] || PLANS.free;\n    }\n    function normalizeDiscountPercent(value){\n      if(value == null || String(value).trim() === \"\") return \"\";\n      let n=Number(String(value).replace(\"%\",\"\").trim());\n      if(!Number.isFinite(n)) return \"\";\n      if(n > 0 && n <= 1) n=n*100;\n      n=Math.max(0,Math.min(100,n));\n      return Number.isInteger(n) ? String(n) : String(Number(n.toFixed(2)));\n    }\n    function normalizePaymentAmountFen(value){\n      const amount=Number(value);\n      return Number.isInteger(amount)&&amount>=0?amount:null;\n    }\n    function formatPaymentAmountFen(amountFen){\n      const amount=normalizePaymentAmountFen(amountFen);\n      if(amount===null)return \"\";\n      const yuan=amount/100;\n      return amount%100===0?`￥${yuan}`:`￥${yuan.toFixed(2)}`;\n    }\n    function splitPriceText(text){\n      const raw=String(text || \"\").trim();\n      const match=raw.match(/^([^0-9]*)([0-9]+(?:\\.[0-9]+)?)(.*)$/);\n      if(!match) return null;\n      return {prefix:match[1] || \"\", amount:Number(match[2]), decimals:(match[2].split(\".\")[1]||\"\").length, suffix:match[3] || \"\"};\n    }\n    function formatDiscountAmount(amount, decimals){\n      if(!Number.isFinite(amount)) return \"\";\n      const fixed=decimals > 0 ? amount.toFixed(Math.min(decimals,2)) : String(Math.round(amount));\n      return fixed.replace(/\\.0+$/,\"\").replace(/(\\.\\d*?)0+$/, \"$1\");\n    }\n    function deriveDiscountPrice(originalText, discountPercent){\n      const raw=String(originalText || \"\").trim();\n      if(!raw) return \"\";\n      const normalized=normalizeDiscountPercent(discountPercent);\n      if(normalized === \"\") return raw;\n      const info=splitPriceText(raw);\n      const pct=Number(normalized);\n      if(!info || !Number.isFinite(pct) || pct < 0) return raw;\n      const amount=info.amount * pct / 100;\n      return `${info.prefix}${formatDiscountAmount(amount,info.decimals)}${info.suffix}`;\n    }\n    function deriveDiscountLabel(discountPercent){\n      const pct=Number(normalizeDiscountPercent(discountPercent));\n      if(!Number.isFinite(pct) || pct <= 0 || pct >= 100) return \"\";\n      const off=100-pct;\n      return `-${Number.isInteger(off)?off:Number(off.toFixed(1))}%`;\n    }\n    function cleanPlanPatch(patch={}){\n      const out={};\n      if(Object.prototype.hasOwnProperty.call(patch,\"enabled\")) out.enabled=!!patch.enabled;\n      if(Object.prototype.hasOwnProperty.call(patch,\"recommended\")) out.recommended=!!patch.recommended;\n      [\"name\",\"shortName\",\"priceText\",\"originalPriceText\",\"durationText\",\"badgeText\",\"description\",\"benefitText\",\"usageText\"].forEach(key=>{\n        if(Object.prototype.hasOwnProperty.call(patch,key)) out[key]=String(patch[key] == null ? \"\" : patch[key]).trim();\n      });\n      if(Object.prototype.hasOwnProperty.call(patch,\"paymentAmountFen\")){\n        const amount=normalizePaymentAmountFen(patch.paymentAmountFen);\n        if(amount!==null)out.paymentAmountFen=amount;\n      }\n      if(Object.prototype.hasOwnProperty.call(patch,\"discountPercent\")) out.discountPercent=normalizeDiscountPercent(patch.discountPercent);\n      return out;\n    }\n    function readPlanSettings(){\n      // 套餐价格只认后端：remote 由 direct-system-adapter 启动时从 /api/v1/subscriptions/plans 预载。\n      // 不再读写 localStorage，避免本机缓存价与后台配置脱节。\n      const remote=window.KGSubscriptionRemotePlanSettings;\n      const out={};\n      if(remote && typeof remote === \"object\"){\n        PLAN_ORDER.forEach(id=>{\n          if(remote[id] && typeof remote[id] === \"object\") out[id]=cleanPlanPatch(remote[id]);\n        });\n      }\n      return out;\n    }\n    function savePlanSettings(settings){\n      const out={};\n      if(settings && typeof settings === \"object\"){\n        PLAN_ORDER.forEach(id=>{\n          if(settings[id] && typeof settings[id] === \"object\") out[id]=cleanPlanPatch(settings[id]);\n        });\n      }\n      window.KGSubscriptionRemotePlanSettings=Object.freeze(out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-plan-change\",{detail:{settings:out}}));\n      refresh();\n      return out;\n    }\n    function setPlanSettings(planId, patch={}){\n      const id=normalizePlanId(planId);\n      const settings=readPlanSettings();\n      settings[id]={...(settings[id]||{}),...cleanPlanPatch(patch)};\n      return savePlanSettings(settings)[id] || {};\n    }\n    function resetPlanSettings(planId){\n      const id=normalizePlanId(planId);\n      const settings=readPlanSettings();\n      delete settings[id];\n      savePlanSettings(settings);\n      return planById(id);\n    }\n    function planById(planId){\n      const base=basePlanById(planId);\n      const settings=readPlanSettings()[base.id] || {};\n      const merged={...base,...settings,id:base.id,level:base.level,billingCycle:base.billingCycle,durationDays:base.durationDays,features:{...base.features},limits:{...base.limits}};\n      const serverPrice=formatPaymentAmountFen(merged.paymentAmountFen);\n      const autoPrice=deriveDiscountPrice(merged.originalPriceText,merged.discountPercent);\n      const discountText=deriveDiscountLabel(merged.discountPercent);\n      return {...merged,priceText:serverPrice || autoPrice || merged.priceText,discountText};\n    }\n    function featureLabel(feature){\n      return FEATURE_LABELS[feature] || feature;\n    }\n    function splitLines(value){\n      return String(value || \"\")\n        .split(/\\r?\\n/)\n        .map(line=>line.trim())\n        .filter(Boolean);\n    }\n    function defaultPlanBenefitItems(plan){\n      return Object.entries(plan && plan.features || {})\n        .filter(([,on])=>!!on)\n        .map(([key])=>featureLabel(key));\n    }\n    function planBenefitItems(plan){\n      const lines=splitLines(plan && plan.benefitText);\n      return lines.length ? lines : defaultPlanBenefitItems(plan);\n    }\n    function defaultPlanUsageText(plan){\n      const limits=plan && plan.limits || {};\n      const keys=[\"dailyTraining\",\"recallMaps\",\"graphNodes\",\"recallNodes\"];\n      const parts=keys.filter(key=>Object.prototype.hasOwnProperty.call(limits,key)).map(key=>{\n        const value=limits[key];\n        const text=Number(value)===-1 ? \"不限\" : String(value);\n        return `${LIMIT_LABELS[key]||key}：${text}`;\n      });\n      if((plan && plan.features && (plan.features.learningPackageImport || plan.features.learningPackageExport)) || Object.prototype.hasOwnProperty.call(limits,\"importPackages\") || Object.prototype.hasOwnProperty.call(limits,\"exportPackages\")){\n        parts.push(\"学习包导入/导出：不限\");\n      }\n      return parts.join(\" · \" );\n    }\n    function planUsageText(plan){\n      const custom=String(plan && plan.usageText || \"\").trim();\n      return custom || defaultPlanUsageText(plan);\n    }\n    function planList(options={}){\n      const includeDisabled=!!options.includeDisabled;\n      return PLAN_ORDER.map(id=>planById(id)).filter(plan=>plan && (includeDisabled || plan.enabled !== false));\n    }\n    function enabledPlanList(){\n      return planList({includeDisabled:false});\n    }\n    function expiresAtForPlan(planId, startedAt=Date.now()){\n      const plan=planById(planId);\n      if(!plan || plan.durationDays <= 0) return 0;\n      return Number(startedAt || Date.now()) + plan.durationDays * 24 * 60 * 60 * 1000;\n    }\n\n    return {\n      PLAN_ALIASES,\n      PLAN_ORDER,\n      PLANS,\n      FEATURE_LABELS,\n      LIMIT_LABELS,\n      readPlanSettings,\n      savePlanSettings,\n      setPlanSettings,\n      resetPlanSettings,\n      normalizePlanId,\n      basePlanById,\n      planById,\n      planList,\n      enabledPlanList,\n      expiresAtForPlan,\n      deriveDiscountPrice,\n      deriveDiscountLabel,\n      formatPaymentAmountFen,\n      featureLabel,\n      planBenefitItems,\n      planUsageText,\n      defaultPlanBenefitItems,\n      defaultPlanUsageText\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-plans.js"],["src/37-subscription-orders.js","\"use strict\";\n\n/*\n * 学员订阅订单模块。\n *\n * 本文件只负责：订单申请、确认开通、取消、删除与订单状态文案。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionOrdersModule = function(ctx={}){\n    const ORDER_KEY = \"kg_student_subscription_orders_v1\";\n\n    const ORDER_STATUS_LABELS = {\n      pending:\"待确认\",\n      approved:\"已开通\",\n      cancelled:\"已取消\"\n    };\n\n    function orderStatusLabel(status){\n      return ORDER_STATUS_LABELS[status] || status || \"未知\";\n    }\n    function cleanOrderStatus(status){\n      status=String(status||\"pending\").trim();\n      return ORDER_STATUS_LABELS[status] ? status : \"pending\";\n    }\n    function normalizeOrder(order={}){\n      const now=Date.now();\n      const plan=ctx.planById(order.planId||\"monthly\");\n      const username=String(order.username||\"\").trim();\n      const createdAt=Number(order.createdAt)||now;\n      return {\n        id:String(order.id||ctx.uid(\"sub_order\")),\n        username,\n        planId:plan.id,\n        planName:String(order.planName||plan.name||plan.id),\n        status:cleanOrderStatus(order.status),\n        amountText:String(order.amountText||plan.priceText||\"\"),\n        originalPriceText:String(order.originalPriceText||plan.originalPriceText||\"\"),\n        discountPercent:String(order.discountPercent||plan.discountPercent||\"\"),\n        discountText:String(order.discountText||plan.discountText||\"\"),\n        createdAt,\n        updatedAt:Number(order.updatedAt)||createdAt,\n        approvedAt:Number(order.approvedAt)||0,\n        cancelledAt:Number(order.cancelledAt)||0,\n        approvedBy:String(order.approvedBy||\"\"),\n        cancelledBy:String(order.cancelledBy||\"\"),\n        actor:String(order.actor||username||ctx.currentUsername()||\"student\"),\n        source:String(order.source||\"student_request\"),\n        note:String(order.note||\"\"),\n        adminNote:String(order.adminNote||\"\"),\n        currentPlanId:String(order.currentPlanId||\"\"),\n        currentPlanName:String(order.currentPlanName||\"\"),\n        snapshot:order.snapshot && typeof order.snapshot===\"object\" ? order.snapshot : {\n          planId:plan.id,\n          planName:plan.name,\n          priceText:plan.priceText,\n          originalPriceText:plan.originalPriceText,\n          discountPercent:plan.discountPercent,\n          discountText:plan.discountText,\n          usageText:ctx.planUsageText(plan),\n          benefits:ctx.planBenefitItems(plan)\n        }\n      };\n    }\n    function readOrders(){\n      const raw=ctx.readJSON(ORDER_KEY,[]);\n      const list=Array.isArray(raw) ? raw : [];\n      return list.map(normalizeOrder).filter(order=>order.id && order.username);\n    }\n    function saveOrders(list){\n      const out=(Array.isArray(list)?list:[]).map(normalizeOrder).filter(order=>order.id && order.username).slice(0,500);\n      ctx.writeJSON(ORDER_KEY,out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-order-change\",{detail:{orders:out}}));\n      return out;\n    }\n    function orderList(options={}){\n      let list=readOrders();\n      if(options.username) list=list.filter(order=>order.username===String(options.username).trim());\n      if(options.status) list=list.filter(order=>order.status===String(options.status).trim());\n      return list.sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));\n    }\n    function pendingOrders(){\n      return orderList({status:\"pending\"});\n    }\n    function currentUserOrders(){\n      const username=ctx.currentUsername();\n      return username ? orderList({username}) : [];\n    }\n    function hasPendingOrder(username,planId){\n      username=String(username||ctx.currentUsername()||\"\").trim();\n      planId=ctx.normalizePlanId(planId||\"monthly\");\n      return !!orderList({username,status:\"pending\"}).find(order=>order.planId===planId);\n    }\n    function createOrder(planId,options={}){\n      const plan=ctx.planById(planId||\"monthly\");\n      const user=options.user || ctx.currentUser();\n      const username=String(options.username || (user&&user.username) || ctx.currentUsername() || \"\").trim();\n      if(!username) return {ok:false,message:\"请先登录学员账号后再提交订阅申请。\"};\n      const role=String(options.role || (user&&user.role) || ctx.currentRole() || \"guest\");\n      if(role===\"admin\"||role===\"teacher\") return {ok:false,message:\"当前身份不需要订阅，可直接使用管理或教学能力。\"};\n      if(role===\"viewer\"||role===\"guest\") return {ok:false,message:\"游客不进入订阅体系，请切换为学员账号后提交订阅申请。\"};\n      if(role!==\"student\") return {ok:false,message:\"只有学员账号需要开通订阅。\"};\n      if(plan.id===\"free\") return {ok:false,message:\"免费学员无需购买，可直接使用免费权益。\"};\n      const existing=orderList({username,status:\"pending\"}).find(order=>order.planId===plan.id);\n      if(existing) return {ok:true,duplicate:true,order:existing,message:`你已经提交过“${plan.name}”开通申请，管理员确认后会自动生效。`};\n      const current=ctx.subscriptionFor(username) || ctx.defaultSubscription(username);\n      const currentPlan=ctx.planById(current.planId||\"free\");\n      const order=normalizeOrder({\n        id:ctx.uid(\"sub_order\"),\n        username,\n        planId:plan.id,\n        planName:plan.name,\n        status:\"pending\",\n        amountText:plan.priceText||\"\",\n        originalPriceText:plan.originalPriceText||\"\",\n        discountPercent:plan.discountPercent||\"\",\n        discountText:plan.discountText||\"\",\n        createdAt:Date.now(),\n        updatedAt:Date.now(),\n        actor:username,\n        source:\"student_request\",\n        note:String(options.note||\"\"),\n        currentPlanId:currentPlan.id,\n        currentPlanName:currentPlan.name,\n        snapshot:{\n          planId:plan.id,\n          planName:plan.name,\n          priceText:plan.priceText,\n          originalPriceText:plan.originalPriceText,\n          discountPercent:plan.discountPercent,\n          discountText:plan.discountText,\n          usageText:ctx.planUsageText(plan),\n          benefits:ctx.planBenefitItems(plan)\n        }\n      });\n      const orders=readOrders();\n      orders.unshift(order);\n      saveOrders(orders);\n      ctx.logAction(\"提交订阅申请\",username,`${plan.name} · ${plan.priceText||\"待配置\"}`);\n      return {ok:true,order,message:`“${plan.name}”订阅申请已提交，请等待管理员确认开通。`};\n    }\n    function approveOrder(orderId,options={}){\n      const orders=readOrders();\n      const idx=orders.findIndex(order=>order.id===orderId);\n      if(idx<0) return {ok:false,message:\"未找到该订阅申请。\"};\n      const order={...orders[idx]};\n      if(order.status!==\"pending\") return {ok:false,message:`该申请当前状态为“${orderStatusLabel(order.status)}”，不能重复确认。`};\n      const actor=String(options.actor || ctx.currentActor() || ctx.currentUsername() || \"system-admin\");\n      const subscription=ctx.renewStudentSubscription(order.username,order.planId,{source:\"order\",orderId:order.id,note:options.note || `订单确认开通：${order.planName}`});\n      order.status=\"approved\";\n      order.approvedAt=Date.now();\n      order.approvedBy=actor;\n      order.updatedAt=Date.now();\n      order.adminNote=String(options.note||order.adminNote||\"\");\n      orders[idx]=normalizeOrder(order);\n      saveOrders(orders);\n      ctx.logAction(\"确认订阅开通\",order.username,`${order.planName} · 订单 ${order.id}`);\n      return {ok:true,order:orders[idx],subscription,message:`已为 ${order.username} 开通 ${order.planName}。`};\n    }\n    function cancelOrder(orderId,options={}){\n      const orders=readOrders();\n      const idx=orders.findIndex(order=>order.id===orderId);\n      if(idx<0) return {ok:false,message:\"未找到该订阅申请。\"};\n      const order={...orders[idx]};\n      if(order.status!==\"pending\") return {ok:false,message:`该申请当前状态为“${orderStatusLabel(order.status)}”，不能取消。`};\n      const actor=String(options.actor || ctx.currentActor() || ctx.currentUsername() || \"system-admin\");\n      order.status=\"cancelled\";\n      order.cancelledAt=Date.now();\n      order.cancelledBy=actor;\n      order.updatedAt=Date.now();\n      order.adminNote=String(options.note||order.adminNote||\"\");\n      orders[idx]=normalizeOrder(order);\n      saveOrders(orders);\n      ctx.logAction(\"取消订阅申请\",order.username,`${order.planName} · 订单 ${order.id}`);\n      return {ok:true,order:orders[idx],message:`已取消 ${order.username} 的 ${order.planName} 申请。`};\n    }\n    function removeOrder(orderId){\n      const orders=readOrders();\n      const next=orders.filter(order=>order.id!==orderId);\n      if(next.length===orders.length) return false;\n      saveOrders(next);\n      return true;\n    }\n\n    return {\n      ORDER_KEY,\n      ORDER_STATUS_LABELS,\n      readOrders,\n      saveOrders,\n      orderList,\n      pendingOrders,\n      currentUserOrders,\n      hasPendingOrder,\n      createOrder,\n      approveOrder,\n      cancelOrder,\n      removeOrder,\n      orderStatusLabel\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-orders.js"],["src/37-subscription-redeem-codes.js","\"use strict\";\n\n/*\n * 学员订阅卡密模块。\n *\n * 本文件只负责：卡密生成、查询、启停、删除与学员兑换。\n * 对外仍由 37-subscription-core.js 汇总到 window.KGSubscription。\n */\n(function(){\n  window.KGSubscriptionRedeemCodesModule = function(ctx={}){\n    const REDEEM_CODE_KEY = \"kg_student_subscription_redeem_codes_v1\";\n\n    const REDEEM_CODE_STATUS_LABELS = {\n      unused:\"未使用\",\n      used:\"已使用\",\n      disabled:\"已停用\"\n    };\n\n    function normalizeRedeemCodeText(value){\n      return String(value||\"\").trim().toUpperCase().replace(/\\s+/g,\"\");\n    }\n    function redeemCodeStatusLabel(status){\n      return REDEEM_CODE_STATUS_LABELS[status] || status || \"未知\";\n    }\n    function cleanRedeemCodeStatus(status){\n      status=String(status||\"unused\").trim();\n      return REDEEM_CODE_STATUS_LABELS[status] ? status : \"unused\";\n    }\n    function normalizeRedeemCode(record={}){\n      const now=Date.now();\n      const plan=ctx.planById(record.planId||\"monthly\");\n      const code=normalizeRedeemCodeText(record.code || randomRedeemCode());\n      const createdAt=Number(record.createdAt)||now;\n      return {\n        id:String(record.id||ctx.uid(\"redeem_code\")),\n        code,\n        planId:plan.id,\n        planName:String(record.planName||plan.name||plan.id),\n        status:cleanRedeemCodeStatus(record.status),\n        createdAt,\n        updatedAt:Number(record.updatedAt)||createdAt,\n        usedAt:Number(record.usedAt)||0,\n        usedBy:String(record.usedBy||\"\"),\n        createdBy:String(record.createdBy||ctx.currentUsername()||\"system-admin\"),\n        note:String(record.note||\"\"),\n        source:String(record.source||\"admin\")\n      };\n    }\n    function readRedeemCodes(){\n      const raw=ctx.readJSON(REDEEM_CODE_KEY,[]);\n      const list=Array.isArray(raw) ? raw : [];\n      return list.map(normalizeRedeemCode).filter(item=>item.code);\n    }\n    function saveRedeemCodes(list){\n      const seen=new Set();\n      const out=(Array.isArray(list)?list:[]).map(normalizeRedeemCode).filter(item=>{\n        if(!item.code || seen.has(item.code))return false;\n        seen.add(item.code);\n        return true;\n      }).slice(0,2000);\n      ctx.writeJSON(REDEEM_CODE_KEY,out);\n      window.dispatchEvent(new CustomEvent(\"kg-subscription-redeem-code-change\",{detail:{codes:out}}));\n      return out;\n    }\n    function redeemCodeList(options={}){\n      let list=readRedeemCodes();\n      if(options.status) list=list.filter(item=>item.status===String(options.status));\n      if(options.planId) list=list.filter(item=>item.planId===ctx.normalizePlanId(options.planId));\n      if(options.keyword){\n        const kw=normalizeRedeemCodeText(options.keyword);\n        list=list.filter(item=>item.code.includes(kw) || String(item.usedBy||\"\").includes(options.keyword));\n      }\n      return list.sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0));\n    }\n    function randomCodeGroup(len=4){\n      const chars=\"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\";\n      let out=\"\";\n      const c=globalThis.crypto;\n      if(c && c.getRandomValues){\n        const arr=new Uint8Array(len);\n        c.getRandomValues(arr);\n        for(let i=0;i<len;i++) out+=chars[arr[i]%chars.length];\n      }else{\n        for(let i=0;i<len;i++) out+=chars[Math.floor(Math.random()*chars.length)];\n      }\n      return out;\n    }\n    function randomRedeemCode(prefix=\"VIP\"){\n      const safePrefix=normalizeRedeemCodeText(prefix||\"VIP\").replace(/[^A-Z0-9]/g,\"\").slice(0,8)||\"VIP\";\n      return `${safePrefix}-${randomCodeGroup()}-${randomCodeGroup()}-${randomCodeGroup()}`;\n    }\n    function generateRedeemCodes(options={}){\n      const plan=ctx.planById(options.planId||\"monthly\");\n      if(plan.id===\"free\") return {ok:false,message:\"免费学员无需生成卡密。\"};\n      const count=Math.max(1,Math.min(200,Math.round(Number(options.count)||1)));\n      const prefix=options.prefix || (plan.shortName || plan.id || \"VIP\");\n      const note=String(options.note||\"\");\n      const codes=readRedeemCodes();\n      const existing=new Set(codes.map(item=>item.code));\n      const created=[];\n      let guard=0;\n      while(created.length<count && guard<count*20){\n        guard++;\n        const code=randomRedeemCode(prefix);\n        if(existing.has(code))continue;\n        existing.add(code);\n        created.push(normalizeRedeemCode({\n          id:ctx.uid(\"redeem_code\"),\n          code,\n          planId:plan.id,\n          planName:plan.name,\n          status:\"unused\",\n          createdAt:Date.now(),\n          updatedAt:Date.now(),\n          createdBy:String(options.createdBy||ctx.currentUsername()||\"system-admin\"),\n          note\n        }));\n      }\n      if(!created.length) return {ok:false,message:\"卡密生成失败，请重试。\"};\n      saveRedeemCodes([...created,...codes]);\n      ctx.logAction(\"生成订阅卡密\",\"SYSTEM\",`${plan.name} × ${created.length}`);\n      return {ok:true,codes:created,message:`已生成 ${created.length} 张 ${plan.name} 卡密。`};\n    }\n    function updateRedeemCode(id,patch={}){\n      const list=readRedeemCodes();\n      const idx=list.findIndex(item=>item.id===id || item.code===normalizeRedeemCodeText(id));\n      if(idx<0) return null;\n      const next=normalizeRedeemCode({...list[idx],...patch,updatedAt:Date.now()});\n      list[idx]=next;\n      saveRedeemCodes(list);\n      return next;\n    }\n    function disableRedeemCode(id){\n      const code=updateRedeemCode(id,{status:\"disabled\"});\n      if(code) ctx.logAction(\"停用订阅卡密\",\"SYSTEM\",code.code);\n      return code;\n    }\n    function enableRedeemCode(id){\n      const code=updateRedeemCode(id,{status:\"unused\",usedAt:0,usedBy:\"\"});\n      if(code) ctx.logAction(\"启用订阅卡密\",\"SYSTEM\",code.code);\n      return code;\n    }\n    function removeRedeemCode(id){\n      const list=readRedeemCodes();\n      const target=list.find(item=>item.id===id || item.code===normalizeRedeemCodeText(id));\n      const next=list.filter(item=>item.id!==id && item.code!==normalizeRedeemCodeText(id));\n      if(next.length===list.length) return false;\n      saveRedeemCodes(next);\n      ctx.logAction(\"删除订阅卡密\",\"SYSTEM\",target?target.code:String(id||\"\"));\n      return true;\n    }\n    function redeemCode(input,options={}){\n      const codeText=normalizeRedeemCodeText(input);\n      if(!codeText) return {ok:false,message:\"请输入卡密。\"};\n      const user=options.user || ctx.currentUser();\n      const username=String(options.username || (user&&user.username) || ctx.currentUsername() || \"\").trim();\n      if(!username) return {ok:false,message:\"请先登录学员账号后再使用卡密。\"};\n      const role=String(options.role || (user&&user.role) || ctx.currentRole() || \"guest\");\n      if(role===\"admin\"||role===\"teacher\") return {ok:false,message:\"当前身份不需要订阅卡密。\"};\n      if(role===\"viewer\"||role===\"guest\") return {ok:false,message:\"游客不进入订阅体系，请切换为学员账号后使用卡密。\"};\n      if(role!==\"student\") return {ok:false,message:\"只有学员账号可以使用订阅卡密。\"};\n      const list=readRedeemCodes();\n      const idx=list.findIndex(item=>item.code===codeText);\n      if(idx<0) return {ok:false,message:\"卡密不存在，请核对后重试。\"};\n      const item={...list[idx]};\n      if(item.status===\"used\") return {ok:false,message:`该卡密已被 ${item.usedBy||\"其他账号\"} 使用。`};\n      if(item.status===\"disabled\") return {ok:false,message:\"该卡密已停用，请联系管理员。\"};\n      const subscription=ctx.renewStudentSubscription(username,item.planId,{source:\"redeem_code\",orderId:item.id,note:`卡密兑换：${item.code}`});\n      item.status=\"used\";\n      item.usedAt=Date.now();\n      item.usedBy=username;\n      item.updatedAt=Date.now();\n      list[idx]=normalizeRedeemCode(item);\n      saveRedeemCodes(list);\n      ctx.logAction(\"兑换订阅卡密\",username,`${item.planName} · ${item.code}`);\n      return {ok:true,code:list[idx],subscription,message:`卡密兑换成功，已开通/续费 ${item.planName}。`};\n    }\n\n    return {\n      REDEEM_CODE_KEY,\n      REDEEM_CODE_STATUS_LABELS,\n      readRedeemCodes,\n      saveRedeemCodes,\n      redeemCodeList,\n      generateRedeemCodes,\n      redeemCode,\n      disableRedeemCode,\n      enableRedeemCode,\n      removeRedeemCode,\n      redeemCodeStatusLabel\n    };\n  };\n})();\n//# sourceURL=src/37-subscription-redeem-codes.js"],["src/37-subscription-core.js","\"use strict\";\n\n/*\n * 学员订阅权益核心模块。\n *\n * 设计边界：\n * - admin 管理员：系统管理角色，自动绕过订阅限制。\n * - teacher 教师/教研：教学维护角色，自动绕过订阅限制。\n * - student 学员：唯一需要订阅权益判断的角色。\n * - viewer 游客：体验/只读角色，不进入订阅体系，只能使用公开示例能力。\n * - guest 未登录访客：不进入订阅体系。\n *\n * 当前版本仍基于 localStorage，正式商业化时应改为后端校验。\n *\n * 基线重构 A：套餐、订单、卡密已拆到独立模块；本文件保留统一入口、\n * 订阅状态、权益校验、页面装饰和 window.KGSubscription 对外 API。\n */\n(function(){\n  const Auth = window.KGAuthCore || {};\n  const Store = window.KGAppStorage || Auth.storage || {};\n  const STORAGE_KEY = \"kg_student_subscriptions_v1\";\n  const MIGRATION_KEY = \"kg_subscription_plan_model_v2_migrated\";\n  const ACTIVE_STATUSES = new Set([\"active\",\"trial\",\"manual\"]);\n\n  const STATUS_LABELS = {\n    active:\"有效\",\n    expired:\"已过期\",\n    paused:\"已停用\",\n    cancelled:\"已取消\",\n    trial:\"试用中\",\n    manual:\"手动开通\"\n  };\n\n  function readJSON(key,fallback){\n    if(Auth.readJSON) return Auth.readJSON(key,fallback);\n    if(Store.readJSON) return Store.readJSON(key,fallback);\n    return (()=>{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback}catch(e){return fallback}})();\n  }\n  function writeJSON(key,value){\n    if(Auth.writeJSON) return Auth.writeJSON(key,value);\n    if(Store.writeJSON) return Store.writeJSON(key,value);\n    return (()=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){return false}})();\n  }\n  function roleApi(){\n    return window.KGRolePermissions || null;\n  }\n  function currentUser(){\n    if(Auth.currentUser) return Auth.currentUser();\n    const api=roleApi();\n    return api && typeof api.currentUser===\"function\" ? api.currentUser() : null;\n  }\n  function currentRole(){\n    const api=roleApi();\n    return api && typeof api.currentRole===\"function\" ? api.currentRole() : \"guest\";\n  }\n  function currentUsername(){\n    if(Auth.currentUsername) return Auth.currentUsername();\n    const user=currentUser();\n    return user && user.username || \"\";\n  }\n  function currentActor(){\n    return Auth.currentActor ? Auth.currentActor() : currentUsername();\n  }\n  function uid(prefix=\"sub_order\"){\n    if(Auth.uid) return Auth.uid(prefix);\n    const c=globalThis.crypto;\n    return prefix + \"-\" + (c && c.randomUUID ? c.randomUUID() : Math.random().toString(36).slice(2)+Date.now().toString(36));\n  }\n  function logAction(action, username, detail){\n    if(Auth.logAction) Auth.logAction(action, username, detail);\n  }\n\n  const PlansFactory = window.KGSubscriptionPlansModule;\n  const OrdersFactory = window.KGSubscriptionOrdersModule;\n  const RedeemCodesFactory = window.KGSubscriptionRedeemCodesModule;\n  if(typeof PlansFactory !== \"function\" || typeof OrdersFactory !== \"function\" || typeof RedeemCodesFactory !== \"function\"){\n    console.error(\"订阅模块加载顺序异常：请先加载 plans / orders / redeem-codes，再加载 37-subscription-core.js\");\n    return;\n  }\n\n  const Plans = PlansFactory({readJSON,writeJSON,decorateSubscriptionElements});\n\n  function normalizePlanId(planId){ return Plans.normalizePlanId(planId); }\n  function basePlanById(planId){ return Plans.basePlanById(planId); }\n  function planById(planId){ return Plans.planById(planId); }\n  function planList(options={}){ return Plans.planList(options); }\n  function enabledPlanList(){ return Plans.enabledPlanList(); }\n  function expiresAtForPlan(planId,startedAt=Date.now()){ return Plans.expiresAtForPlan(planId,startedAt); }\n  function readPlanSettings(){ return Plans.readPlanSettings(); }\n  function savePlanSettings(settings){ return Plans.savePlanSettings(settings); }\n  function setPlanSettings(planId,patch={}){ return Plans.setPlanSettings(planId,patch); }\n  function resetPlanSettings(planId){ return Plans.resetPlanSettings(planId); }\n  function deriveDiscountPrice(originalText,discountPercent){ return Plans.deriveDiscountPrice(originalText,discountPercent); }\n  function deriveDiscountLabel(discountPercent){ return Plans.deriveDiscountLabel(discountPercent); }\n  function featureLabel(feature){ return Plans.featureLabel(feature); }\n  function planBenefitItems(plan){ return Plans.planBenefitItems(plan); }\n  function planUsageText(plan){ return Plans.planUsageText(plan); }\n  function defaultPlanBenefitItems(plan){ return Plans.defaultPlanBenefitItems(plan); }\n  function defaultPlanUsageText(plan){ return Plans.defaultPlanUsageText(plan); }\n\n  function isStudentRole(role=currentRole()){\n    return role === \"student\";\n  }\n  function isBypassRole(role=currentRole()){\n    return role === \"admin\" || role === \"teacher\";\n  }\n  function isVisitorRole(role=currentRole()){\n    return role === \"viewer\" || role === \"guest\";\n  }\n  function normalizeStatus(status){\n    const next=String(status || \"active\").trim();\n    return STATUS_LABELS[next] ? next : \"active\";\n  }\n  function readSubscriptions(){\n    const map=readJSON(STORAGE_KEY,{});\n    return map && typeof map === \"object\" ? map : {};\n  }\n  function saveSubscriptions(map){\n    writeJSON(STORAGE_KEY,map && typeof map === \"object\" ? map : {});\n  }\n  function defaultSubscription(username=currentUsername()){\n    const now=Date.now();\n    return {\n      username,\n      planId:\"free\",\n      status:\"active\",\n      startedAt:now,\n      expiresAt:0,\n      updatedAt:now,\n      source:\"default\",\n      orderId:\"\",\n      note:\"\"\n    };\n  }\n  function normalizeSubscription(sub,username=currentUsername()){\n    sub=sub && typeof sub === \"object\" ? sub : {};\n    const planId=normalizePlanId(sub.planId);\n    const startedAt=Number(sub.startedAt)||Date.now();\n    let expiresAt=Number(sub.expiresAt)||0;\n    const plan=planById(planId);\n    if(plan.durationDays === -1) expiresAt=0;\n    return {\n      ...defaultSubscription(username),\n      ...sub,\n      username:sub.username || username,\n      planId,\n      status:normalizeStatus(sub.status),\n      startedAt,\n      expiresAt,\n      updatedAt:Number(sub.updatedAt)||0,\n      source:sub.source || \"manual\",\n      orderId:sub.orderId || \"\",\n      note:sub.note || \"\"\n    };\n  }\n  function isExpired(sub){\n    const plan=planById(sub && sub.planId);\n    if(plan.durationDays === -1) return false;\n    return !!(sub && Number(sub.expiresAt) && Date.now() > Number(sub.expiresAt));\n  }\n  function effectiveSubscription(sub,username=currentUsername()){\n    const next=normalizeSubscription(sub,username);\n    if(isExpired(next)) return {...next,status:\"expired\"};\n    return next;\n  }\n  function subscriptionFor(username){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const map=readSubscriptions();\n    return effectiveSubscription(map[username],username);\n  }\n  function currentSubscription(){\n    const role=currentRole();\n    const user=currentUser();\n    if(!user || !isStudentRole(role)) return null;\n    return subscriptionFor(user.username);\n  }\n  function currentPlan(){\n    const role=currentRole();\n    if(isBypassRole(role)){\n      return {id:\"role_bypass\",name:\"管理/教学免订阅\",shortName:\"免订阅\",level:99,features:{},limits:{},durationText:\"不需要订阅\"};\n    }\n    if(isVisitorRole(role)){\n      return {id:\"visitor\",name:\"游客体验\",shortName:\"游客\",level:-1,features:{demoOnly:true},limits:{},durationText:\"体验\"};\n    }\n    const sub=currentSubscription();\n    return planById(sub && sub.planId);\n  }\n  function statusLabel(status){\n    return STATUS_LABELS[status] || status || \"未知\";\n  }\n  function canUse(feature, options={}){\n    const role=currentRole();\n    if(isBypassRole(role)) return true;\n    if(isVisitorRole(role)) return !!options.allowVisitorDemo;\n    if(!isStudentRole(role)) return false;\n    const sub=currentSubscription();\n    if(!sub || !ACTIVE_STATUSES.has(sub.status)) return false;\n    const plan=planById(sub.planId);\n    if(!feature) return true;\n    return !!(plan && plan.features && plan.features[feature]);\n  }\n  function requireFeature(feature, options={}){\n    const allowed=canUse(feature, options);\n    if(allowed) return true;\n    const role=currentRole();\n    let message=\"\";\n    if(isVisitorRole(role)) message=\"游客不参与订阅，请登录学员账号后使用“\"+featureLabel(feature)+\"”。\";\n    else if(isStudentRole(role)) message=\"当前学员订阅暂未包含“\"+featureLabel(feature)+\"”。\";\n    else message=\"当前角色不可使用“\"+featureLabel(feature)+\"”。\";\n    const status=document.getElementById(\"status\");\n    if(status && typeof window.showStatus===\"function\") window.showStatus(message);\n    else if(status){\n      status.textContent=message;\n      status.classList.add(\"show\");\n      clearTimeout(requireFeature.timer);\n      requireFeature.timer=setTimeout(()=>status.classList.remove(\"show\"),2200);\n    }\n    return false;\n  }\n  function usageLimit(key){\n    const role=currentRole();\n    if(isBypassRole(role)) return -1;\n    if(isVisitorRole(role)) return 0;\n    const plan=currentPlan();\n    return plan && plan.limits && Number.isFinite(Number(plan.limits[key])) ? Number(plan.limits[key]) : 0;\n  }\n  function limitLabel(key){\n    return Plans.LIMIT_LABELS[key] || key;\n  }\n  function remainingUsage(key,currentCount=0){\n    const limit=usageLimit(key);\n    if(limit < 0) return -1;\n    return Math.max(0,limit-(Number(currentCount)||0));\n  }\n  function showSubscriptionMessage(message){\n    const text=String(message||\"\").trim();\n    if(!text) return;\n    if(typeof window.showStatus===\"function\"){\n      window.showStatus(text);\n      return;\n    }\n    const status=document.getElementById(\"status\");\n    if(status){\n      status.textContent=text;\n      status.classList.add(\"show\");\n      clearTimeout(showSubscriptionMessage.timer);\n      showSubscriptionMessage.timer=setTimeout(()=>status.classList.remove(\"show\"),2800);\n      return;\n    }\n    let toast=document.getElementById(\"subscriptionLimitToast\");\n    if(!toast){\n      toast=document.createElement(\"div\");\n      toast.id=\"subscriptionLimitToast\";\n      toast.className=\"subscription-limit-toast\";\n      document.body.appendChild(toast);\n    }\n    toast.textContent=text;\n    toast.classList.add(\"show\");\n    clearTimeout(showSubscriptionMessage.toastTimer);\n    showSubscriptionMessage.toastTimer=setTimeout(()=>toast.classList.remove(\"show\"),3000);\n  }\n  function usageLimitMessage(key,currentCount=0,addCount=1,options={}){\n    const role=currentRole();\n    const label=options.label || limitLabel(key);\n    if(isVisitorRole(role)) return `游客账号不能新增${label}，请登录学员账号后使用。`;\n    const limit=usageLimit(key);\n    if(limit < 0) return \"\";\n    const current=Math.max(0,Number(currentCount)||0);\n    const add=Math.max(1,Number(addCount)||1);\n    const plan=currentPlan();\n    const planName=plan && (plan.name||plan.shortName) || \"当前套餐\";\n    return `${planName}的${label}上限为 ${limit} 个，当前已有 ${current} 个，本次还需新增 ${add} 个。升级会员后可解除此限制。`;\n  }\n  function canAddUsage(key,currentCount=0,addCount=1){\n    const limit=usageLimit(key);\n    if(limit < 0) return true;\n    const current=Math.max(0,Number(currentCount)||0);\n    const add=Math.max(1,Number(addCount)||1);\n    return current + add <= limit;\n  }\n  function requireUsageLimit(key,currentCount=0,addCount=1,options={}){\n    if(canAddUsage(key,currentCount,addCount)) return true;\n    showSubscriptionMessage(options.message || usageLimitMessage(key,currentCount,addCount,options));\n    return false;\n  }\n  function setStudentSubscription(username, patch={}){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const map=readSubscriptions();\n    const previous=normalizeSubscription(map[username],username);\n    const planId=patch.planId != null ? normalizePlanId(patch.planId) : previous.planId;\n    const startedAt=patch.startedAt != null ? Number(patch.startedAt)||Date.now() : (previous.startedAt || Date.now());\n    let expiresAt=patch.expiresAt != null ? Number(patch.expiresAt)||0 : previous.expiresAt;\n    if(patch.planId != null && patch.expiresAt == null) expiresAt=expiresAtForPlan(planId,startedAt);\n    const next=normalizeSubscription({\n      ...previous,\n      ...patch,\n      username,\n      planId,\n      startedAt,\n      expiresAt,\n      updatedAt:Date.now()\n    },username);\n    map[username]=next;\n    saveSubscriptions(map);\n    window.dispatchEvent(new CustomEvent(\"kg-subscription-change\",{detail:{username,subscription:next}}));\n    decorateSubscriptionElements();\n    return next;\n  }\n  function subscriptionText(){\n    const role=currentRole();\n    if(isBypassRole(role)) return \"免订阅\";\n    if(role===\"viewer\") return \"游客体验\";\n    if(role===\"guest\") return \"未登录游客\";\n    const sub=currentSubscription();\n    if(!sub) return \"无订阅\";\n    const plan=planById(sub.planId);\n    if(ACTIVE_STATUSES.has(sub.status)) return plan.shortName || plan.name || \"免费\";\n    return (plan.shortName || plan.name || \"订阅\") + \" · \" + statusLabel(sub.status);\n  }\n  function formatDate(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"永久有效\";\n    try{return new Date(n).toLocaleDateString(\"zh-CN\")}catch(e){return \"—\"}\n  }\n  function formatDateTime(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"永久有效\";\n    try{return new Date(n).toLocaleString(\"zh-CN\",{year:\"numeric\",month:\"2-digit\",day:\"2-digit\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false})}catch(e){return \"—\"}\n  }\n  function countdownDaysText(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"长期有效\";\n    const diff=n-Date.now();\n    if(diff <= 0) return \"已到期\";\n    return `剩余 ${Math.ceil(diff/(24*60*60*1000))} 天`;\n  }\n  function dateInputValue(ts){\n    const n=Number(ts)||0;\n    if(!n) return \"\";\n    const d=new Date(n - new Date(n).getTimezoneOffset()*60000);\n    return d.toISOString().slice(0,10);\n  }\n  function dateInputToTime(value,endOfDay=false){\n    if(!value) return 0;\n    const suffix=endOfDay ? \"T23:59:59\" : \"T00:00:00\";\n    const t=new Date(String(value)+suffix).getTime();\n    return Number.isFinite(t) ? t : 0;\n  }\n  function renewStudentSubscription(username,planId,options={}){\n    username=String(username||\"\").trim();\n    if(!username) return null;\n    const plan=planById(planId||\"monthly\");\n    const previous=subscriptionFor(username) || defaultSubscription(username);\n    const now=Date.now();\n    const extend=options.extend !== false;\n    const base=extend && plan.durationDays > 0 && previous.expiresAt && previous.expiresAt > now ? previous.expiresAt : now;\n    const startedAt=Number(options.startedAt)||now;\n    const expiresAt=plan.durationDays === -1 ? 0 : (plan.durationDays > 0 ? base + plan.durationDays*24*60*60*1000 : 0);\n    return setStudentSubscription(username,{\n      planId:plan.id,\n      status:options.status || \"active\",\n      startedAt,\n      expiresAt,\n      source:options.source || \"manual\",\n      orderId:options.orderId || previous.orderId || \"\",\n      note:options.note != null ? String(options.note) : previous.note || \"\"\n    });\n  }\n  function pauseStudentSubscription(username,note=\"\"){\n    const previous=subscriptionFor(username) || defaultSubscription(username);\n    return setStudentSubscription(username,{...previous,status:\"paused\",note:String(note||previous.note||\"\"),source:previous.source||\"manual\"});\n  }\n  function activateFreeSubscription(username,note=\"\"){\n    return setStudentSubscription(username,{planId:\"free\",status:\"active\",startedAt:Date.now(),expiresAt:0,source:\"manual\",note:String(note||\"\")});\n  }\n  function subscriptionSummary(username=currentUsername()){\n    const sub=subscriptionFor(username);\n    if(!sub) return {subscription:null,plan:planById(\"free\"),statusText:\"未开通\",expiresText:\"—\",expiresFullText:\"—\",countdownText:\"—\"};\n    const plan=planById(sub.planId);\n    const unlimited=plan.durationDays === -1 || !sub.expiresAt;\n    return {\n      subscription:sub,\n      plan,\n      statusText:statusLabel(sub.status),\n      expiresText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : formatDate(sub.expiresAt),\n      expiresFullText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : formatDateTime(sub.expiresAt),\n      countdownText:unlimited ? (plan.durationDays === -1 ? \"永久有效\" : \"长期有效\") : countdownDaysText(sub.expiresAt)\n    };\n  }\n  function migrateLegacySubscriptions(){\n    if(readJSON(MIGRATION_KEY,false)) return false;\n    const map=readSubscriptions();\n    let changed=false;\n    Object.keys(map).forEach(username=>{\n      const before=map[username];\n      if(!before || typeof before !== \"object\") return;\n      const next=normalizeSubscription(before,username);\n      if(next.planId !== before.planId || next.status !== before.status){\n        map[username]=next;\n        changed=true;\n      }\n    });\n    if(changed) saveSubscriptions(map);\n    writeJSON(MIGRATION_KEY,true);\n    return changed;\n  }\n  function decorateSubscriptionElements(root=document){\n    const scope=root||document;\n    scope.querySelectorAll(\"[data-subscription-feature]\").forEach(el=>{\n      const feature=el.dataset.subscriptionFeature;\n      const mode=el.dataset.subscriptionMode || \"disable\";\n      const allowed=canUse(feature);\n      el.classList.toggle(\"subscription-locked\",!allowed);\n      el.setAttribute(\"aria-disabled\",String(!allowed));\n      if(mode===\"hide\") el.hidden=!allowed;\n      else if(\"disabled\" in el) el.disabled=!allowed;\n      if(!allowed && !el.dataset.subscriptionTitle){\n        el.dataset.subscriptionTitle=el.title || \"\";\n        el.title=\"当前学员订阅暂未包含：\"+featureLabel(feature);\n      }else if(allowed && el.dataset.subscriptionTitle!=null){\n        el.title=el.dataset.subscriptionTitle;\n      }\n    });\n    const status=scope.querySelector(\"[data-subscription-status]\");\n    if(status) status.textContent=subscriptionText();\n    const current=currentSubscription();\n    const hasActivePaidMembership=!!(current\n      && ACTIVE_STATUSES.has(current.status)\n      && current.planId\n      && current.planId!==\"free\");\n    scope.querySelectorAll(\"#upgradeMemberBtn,#accountMenuUpgradeBtn,[data-subscription-upgrade-label]\").forEach(btn=>{\n      btn.hidden=hasActivePaidMembership;\n      if(!hasActivePaidMembership) btn.textContent=\"升级会员\";\n    });\n  }\n\n  const Orders = OrdersFactory({\n    readJSON,\n    writeJSON,\n    currentUser,\n    currentRole,\n    currentUsername,\n    currentActor,\n    uid,\n    logAction,\n    normalizePlanId,\n    planById,\n    planUsageText,\n    planBenefitItems,\n    subscriptionFor,\n    defaultSubscription,\n    renewStudentSubscription\n  });\n\n  const RedeemCodes = RedeemCodesFactory({\n    readJSON,\n    writeJSON,\n    currentUser,\n    currentRole,\n    currentUsername,\n    uid,\n    logAction,\n    normalizePlanId,\n    planById,\n    renewStudentSubscription\n  });\n\n  function readOrders(){ return Orders.readOrders(); }\n  function saveOrders(list){ return Orders.saveOrders(list); }\n  function orderList(options={}){ return Orders.orderList(options); }\n  function pendingOrders(){ return Orders.pendingOrders(); }\n  function currentUserOrders(){ return Orders.currentUserOrders(); }\n  function hasPendingOrder(username,planId){ return Orders.hasPendingOrder(username,planId); }\n  function createOrder(planId,options={}){ return Orders.createOrder(planId,options); }\n  function approveOrder(orderId,options={}){ return Orders.approveOrder(orderId,options); }\n  function cancelOrder(orderId,options={}){ return Orders.cancelOrder(orderId,options); }\n  function removeOrder(orderId){ return Orders.removeOrder(orderId); }\n  function orderStatusLabel(status){ return Orders.orderStatusLabel(status); }\n\n  function readRedeemCodes(){ return RedeemCodes.readRedeemCodes(); }\n  function saveRedeemCodes(list){ return RedeemCodes.saveRedeemCodes(list); }\n  function redeemCodeList(options={}){ return RedeemCodes.redeemCodeList(options); }\n  function generateRedeemCodes(options={}){ return RedeemCodes.generateRedeemCodes(options); }\n  function redeemCode(input,options={}){ return RedeemCodes.redeemCode(input,options); }\n  function disableRedeemCode(id){ return RedeemCodes.disableRedeemCode(id); }\n  function enableRedeemCode(id){ return RedeemCodes.enableRedeemCode(id); }\n  function removeRedeemCode(id){ return RedeemCodes.removeRedeemCode(id); }\n  function redeemCodeStatusLabel(status){ return RedeemCodes.redeemCodeStatusLabel(status); }\n\n  migrateLegacySubscriptions();\n  document.addEventListener(\"DOMContentLoaded\",()=>decorateSubscriptionElements());\n  window.addEventListener(\"kg-role-theme-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-auth-session-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-auth-users-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-subscription-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"kg-subscription-plan-change\",()=>setTimeout(decorateSubscriptionElements,0));\n  window.addEventListener(\"storage\",event=>{\n    if(!event.key || event.key===STORAGE_KEY || event.key===Orders.ORDER_KEY || event.key===RedeemCodes.REDEEM_CODE_KEY || event.key.indexOf(\"kg_local_\")===0) setTimeout(decorateSubscriptionElements,0);\n  });\n\n  window.KGSubscription={\n    STORAGE_KEY,\n    ORDER_KEY:Orders.ORDER_KEY,\n    REDEEM_CODE_KEY:RedeemCodes.REDEEM_CODE_KEY,\n    MIGRATION_KEY,\n    PLANS:Plans.PLANS,\n    PLAN_ORDER:Plans.PLAN_ORDER,\n    PLAN_ALIASES:Plans.PLAN_ALIASES,\n    FEATURE_LABELS:Plans.FEATURE_LABELS,\n    LIMIT_LABELS:Plans.LIMIT_LABELS,\n    STATUS_LABELS,\n    ORDER_STATUS_LABELS:Orders.ORDER_STATUS_LABELS,\n    REDEEM_CODE_STATUS_LABELS:RedeemCodes.REDEEM_CODE_STATUS_LABELS,\n    readSubscriptions,\n    saveSubscriptions,\n    readOrders,\n    saveOrders,\n    readRedeemCodes,\n    saveRedeemCodes,\n    redeemCodeList,\n    generateRedeemCodes,\n    redeemCode,\n    disableRedeemCode,\n    enableRedeemCode,\n    removeRedeemCode,\n    redeemCodeStatusLabel,\n    orderList,\n    pendingOrders,\n    currentUserOrders,\n    hasPendingOrder,\n    createOrder,\n    approveOrder,\n    cancelOrder,\n    removeOrder,\n    orderStatusLabel,\n    readPlanSettings,\n    savePlanSettings,\n    setPlanSettings,\n    resetPlanSettings,\n    normalizePlanId,\n    basePlanById,\n    planById,\n    planList,\n    enabledPlanList,\n    expiresAtForPlan,\n    subscriptionFor,\n    currentSubscription,\n    currentPlan,\n    currentRole,\n    isStudentRole,\n    isBypassRole,\n    isVisitorRole,\n    canUse,\n    requireFeature,\n    usageLimit,\n    limitLabel,\n    remainingUsage,\n    canAddUsage,\n    requireUsageLimit,\n    usageLimitMessage,\n    showSubscriptionMessage,\n    setStudentSubscription,\n    renewStudentSubscription,\n    pauseStudentSubscription,\n    activateFreeSubscription,\n    subscriptionSummary,\n    formatDate,\n    formatDateTime,\n    countdownDaysText,\n    deriveDiscountPrice,\n    deriveDiscountLabel,\n    dateInputValue,\n    dateInputToTime,\n    subscriptionText,\n    decorateSubscriptionElements,\n    featureLabel,\n    planBenefitItems,\n    planUsageText,\n    defaultPlanBenefitItems,\n    defaultPlanUsageText,\n    statusLabel,\n    normalizeSubscription,\n    migrateLegacySubscriptions\n  };\n})();\n//# sourceURL=src/37-subscription-core.js"],["direct-system-adapter.js","'use strict'\n\n;(function (global) {\n  const roleApi = global.KGRolePermissions\n  const wechatApi = global.KGWechatLogin\n  const subscriptionApi = global.KGSubscription\n  let userProfile = null\n  let userLoadPromise\n  // FastAPI 内联注入的会话元数据可同步提供登录态；/me 仍在后台校正。\n  const injectedBootstrap = global.__KG_DIRECT_BOOTSTRAP__\n  if (injectedBootstrap?.authenticated && injectedBootstrap.authUser) {\n    userProfile = injectedBootstrap.authUser\n  }\n  // wechatApi 仅管理端配置保存需要；部分学员页未加载 32-wechat-login.js，不应因此跳过套餐价格预载。\n  if (!roleApi || !subscriptionApi) return\n  const originalSaveTheme = roleApi.saveTheme.bind(roleApi)\n  const originalResetTheme = roleApi.resetTheme.bind(roleApi)\n\n  function errorMessage(payload, status) {\n    const detail = payload?.detail ?? payload?.message ?? payload?.error\n    if (Array.isArray(detail)) return detail.map((item) => item?.msg || String(item)).join('；')\n    return String(detail || `服务器请求失败（${status || 0}）`)\n  }\n\n  function request(method, path, body) {\n    const xhr = new XMLHttpRequest()\n    xhr.open(method, path, false)\n    xhr.withCredentials = true\n    xhr.setRequestHeader('Accept', 'application/json')\n    if (body !== undefined) xhr.setRequestHeader('Content-Type', 'application/json')\n    xhr.send(body === undefined ? null : JSON.stringify(body))\n    let payload = {}\n    try { payload = xhr.responseText ? JSON.parse(xhr.responseText) : {} } catch (_) {}\n    if (xhr.status < 200 || xhr.status >= 300) {\n      throw new Error(errorMessage(payload, xhr.status))\n    }\n    return payload\n  }\n\n  async function requestJson(method, path, body) {\n    const response = await fetch(path, {\n      method,\n      credentials: 'include',\n      headers: body === undefined ? { Accept: 'application/json' } : {\n        Accept: 'application/json',\n        'Content-Type': 'application/json',\n      },\n      body: body === undefined ? undefined : JSON.stringify(body),\n    })\n    let payload = {}\n    try { payload = await response.json() } catch (_) {}\n    if (!response.ok) throw new Error(errorMessage(payload, response.status))\n    return payload\n  }\n\n  global.KGWechatPay = {\n    async createNativeOrder(planId) {\n      return requestJson('POST', '/api/v1/subscriptions/orders', { planId })\n    },\n    async getNativeOrderStatus(orderId) {\n      return requestJson('GET', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/status`)\n    },\n    async cancelNativeOrder(orderId) {\n      return requestJson('POST', `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/self-cancel`)\n    },\n    syncSubscription,\n    nativeOrderQrCodeUrl(orderId) {\n      return `/api/v1/subscriptions/orders/${encodeURIComponent(orderId)}/qrcode`\n    },\n  }\n\n  function toLegacyTheme(theme = {}) {\n    return {\n      primary: theme.primary_color || theme.primary,\n      accent: theme.accent_color || theme.accent,\n      soft: theme.soft_color || theme.soft,\n      text: theme.text_color || theme.text,\n    }\n  }\n\n  function toServerTheme(theme = {}) {\n    return {\n      primary_color: theme.primary,\n      accent_color: theme.accent,\n      soft_color: theme.soft,\n      text_color: theme.text,\n    }\n  }\n\n  function planSettings(plans = []) {\n    return Object.fromEntries(\n      plans\n        .filter((plan) => plan && plan.planId)\n        .map((plan) => [plan.planId, { ...plan, id: undefined, planId: undefined }]),\n    )\n  }\n\n  function cachedRole() {\n    return String(userProfile?.role || 'guest')\n  }\n\n  function isAuthenticated() {\n    return userProfile != null\n  }\n\n  function isAdmin() {\n    return cachedRole() === 'admin'\n  }\n\n  function preloadUserProfile() {\n    if (userProfile || userLoadPromise) return userLoadPromise || Promise.resolve(userProfile)\n    userLoadPromise = requestJson('GET', '/api/v1/auth/me')\n      .then((payload) => {\n        userProfile = payload?.user || null\n        return userProfile\n      })\n      .catch(() => {\n        userProfile = null\n        return null\n      })\n      .finally(() => {\n        userLoadPromise = null\n      })\n    return userLoadPromise\n  }\n\n  function preloadPlans() {\n    const plans = request('GET', '/api/v1/subscriptions/plans').plans || []\n    // 套餐配置以 PostgreSQL 为唯一来源；仅在当前页面内存中提供给旧 UI 模块，\n    // 不把展示配置写回浏览器缓存或运行时状态表。\n    global.KGSubscriptionRemotePlanSettings = Object.freeze(planSettings(plans))\n    global.dispatchEvent(new CustomEvent('kg-subscription-plan-change', {\n      detail: { settings: global.KGSubscriptionRemotePlanSettings },\n    }))\n  }\n\n  function subscriptionTimestamp(value) {\n    const timestamp = Date.parse(value || '')\n    return Number.isFinite(timestamp) ? timestamp : 0\n  }\n\n  function syncSubscription(subscription) {\n    if (!subscription?.username || typeof subscriptionApi.setStudentSubscription !== 'function') return null\n    return subscriptionApi.setStudentSubscription(subscription.username, {\n      planId: subscription.planId,\n      status: subscription.status,\n      startedAt: subscriptionTimestamp(subscription.startedAt),\n      expiresAt: subscriptionTimestamp(subscription.expiresAt),\n      source: subscription.source,\n      note: subscription.note || '',\n    })\n  }\n\n  function preloadSubscription() {\n    const payload = request('GET', '/api/v1/subscriptions/me')\n    global.KGServerEntitlements = Object.freeze({\n      allExamPapers: payload.entitlements?.allExamPapers === true,\n    })\n    return syncSubscription(payload.subscription)\n  }\n\n  function clearEntitlements() {\n    global.KGServerEntitlements = Object.freeze({ allExamPapers: false })\n  }\n\n  // 页面内切换/退出账号时，服务端权益必须跟随当前账号重新拉取；\n  // 否则上一个账号（如会员）的 KGServerEntitlements 会残留，普通账号也被误判为有 VIP 权益。\n  function refreshEntitlementsForCurrentUser(detail = {}) {\n    const username = String(detail.username || global.KGAuthCore?.currentUser?.()?.username || '').trim()\n    try {\n      if (username) preloadSubscription()\n      else clearEntitlements()\n    } catch (error) {\n      console.error('[DirectSystemAdapter] refresh entitlements after auth change failed:', error)\n      clearEntitlements()\n    }\n  }\n\n  function preloadAuthenticatedContext() {\n    preloadUserProfile().then(() => {\n      if (!userProfile) {\n        clearEntitlements()\n      } else {\n        try {\n          const themes = request('GET', '/api/v1/system/themes').themes || {}\n          for (const [role, theme] of Object.entries(themes)) {\n            originalSaveTheme(role, toLegacyTheme(theme))\n          }\n        } catch (error) {\n          console.error('[DirectSystemAdapter] role themes preload failed:', error)\n        }\n\n        try {\n          preloadSubscription()\n        } catch (error) {\n          console.error('[DirectSystemAdapter] subscription preload failed:', error)\n        }\n      }\n\n      if (isAdmin()) {\n        try {\n          const wechat = request('GET', '/api/v1/system/wechat-config').config || {}\n          wechatApi?.applyConfig?.(wechat)\n          const wechatPay = request('GET', '/api/v1/system/wechat-pay-config').config || {}\n          global.KGDirectSystemSettings = { wechatPayConfig: wechatPay }\n        } catch (error) {\n          console.error('[DirectSystemAdapter] admin settings preload failed:', error)\n        }\n      }\n    }).catch((error) => {\n      console.error('[DirectSystemAdapter] preloadAuthenticatedContext failed:', error)\n    })\n  }\n\n  if (typeof global.addEventListener === 'function') {\n    global.addEventListener('kg-auth-session-change', (event) => {\n      const detail = event?.detail || {}\n      const username = String(detail.username || '').trim()\n      const authenticated = detail.authenticated === true\n        || (detail.authenticated !== false && Boolean(username))\n      userProfile = null\n      userLoadPromise = null\n      refreshEntitlementsForCurrentUser(detail)\n      if (authenticated) preloadAuthenticatedContext()\n      else clearEntitlements()\n    })\n  }\n\n  preloadAuthenticatedContext()\n  preloadPlans()\n\n  roleApi.saveTheme = function (role, theme) {\n    const saved = request('PUT', `/api/v1/system/themes/${encodeURIComponent(role)}`, toServerTheme(theme)).theme\n    return originalSaveTheme(role, toLegacyTheme(saved))\n  }\n  roleApi.resetTheme = function (role) {\n    const fallback = roleApi.DEFAULT_THEMES?.[role] || {}\n    const saved = request('PUT', `/api/v1/system/themes/${encodeURIComponent(role)}`, toServerTheme(fallback)).theme\n    originalResetTheme(role)\n    return originalSaveTheme(role, toLegacyTheme(saved))\n  }\n\n  if (wechatApi) {\n    const originalSaveConfig = wechatApi.saveConfig.bind(wechatApi)\n    wechatApi.saveConfig = function (config) {\n      const saved = request('PUT', '/api/v1/system/wechat-config', config).config\n      return originalSaveConfig(saved)\n    }\n  }\n\n  const originalSetPlanSettings = subscriptionApi.setPlanSettings.bind(subscriptionApi)\n  const originalResetPlanSettings = subscriptionApi.resetPlanSettings.bind(subscriptionApi)\n  const originalSavePlanSettings = subscriptionApi.savePlanSettings.bind(subscriptionApi)\n  subscriptionApi.setPlanSettings = function (planId, patch = {}) {\n    const saved = request('PUT', `/api/v1/system/subscription-plans/${encodeURIComponent(planId)}`, patch).plan\n    return originalSetPlanSettings(planId, saved || patch)\n  }\n  subscriptionApi.resetPlanSettings = function (planId) {\n    const base = subscriptionApi.PLANS?.[planId] || {}\n    request('PUT', `/api/v1/system/subscription-plans/${encodeURIComponent(planId)}`, base)\n    return originalResetPlanSettings(planId)\n  }\n  subscriptionApi.savePlanSettings = function (settings = {}) {\n    for (const planId of subscriptionApi.PLAN_ORDER || []) {\n      const patch = settings[planId] || subscriptionApi.PLANS?.[planId] || {}\n      request('PUT', `/api/v1/system/subscription-plans/${encodeURIComponent(planId)}`, patch)\n    }\n    return originalSavePlanSettings(settings)\n  }\n})(window)\n//# sourceURL=direct-system-adapter.js"],["src/33-user-center.js","\"use strict\";\n\n/*\n * 用户中心：当前登录用户自助维护个人资料。\n * 说明：仍然基于 localStorage；正式网络版接入后端后，应改为服务端接口保存。\n */\n(function(){\n  const AUTH_USERS_KEY=\"kg_local_users_v1\";\n  const AUTH_SESSION_KEY=\"kg_local_current_user_v1\";\n  const USER_LOG_KEY=\"kg_user_admin_logs_v1\";\n  const ACTIVE_PAID_MEMBERSHIP_STATUSES=new Set([\"active\",\"trial\",\"manual\"]);\n  const Store=window.KGAppStorage||{};\n\n  const $=id=>document.getElementById(id);\n  function escapeHTML(value){\n    return String(value == null ? \"\" : value).replace(/[&<>\\'\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",\"\\'\":\"&#39;\",'\"':\"&quot;\"}[c]));\n  }\n  const authCore=()=>window.KGAuthCore||null;\n  function readJSON(key,fallback){\n    const core=authCore();\n    if(core&&typeof core.readJSON===\"function\")return core.readJSON(key,fallback);\n    if(Store.readJSON)return Store.readJSON(key,fallback);\n    try{\n      const raw=localStorage.getItem(key);\n      if(!raw)return fallback;\n      const parsed=JSON.parse(raw);\n      return parsed==null?fallback:parsed;\n    }catch(e){return fallback}\n  }\n  function writeJSON(key,value){\n    const core=authCore();\n    if(core&&typeof core.writeJSON===\"function\")return core.writeJSON(key,value);\n    if(Store.writeJSON)return Store.writeJSON(key,value);\n    localStorage.setItem(key,JSON.stringify(value));\n    return true;\n  }\n  function makeSalt(){\n    const core=authCore();\n    return core&&typeof core.makeSalt===\"function\"?core.makeSalt():Math.random().toString(36).slice(2)+Date.now().toString(36);\n  }\n  function passwordHash(username,password,salt){\n    const core=authCore();\n    if(core&&typeof core.passwordHash===\"function\")return core.passwordHash(username,password,salt);\n    let h=2166136261;\n    const str=String(salt)+\"|\"+String(username).toLowerCase()+\"|\"+String(password);\n    for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h+=(h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24)}\n    return (h>>>0).toString(36);\n  }\n  function verifyPassword(username,password,user){\n    const core=authCore();\n    if(core&&typeof core.verifyPassword===\"function\")return core.verifyPassword(username,password,user);\n    return passwordHash(username,password,user&&user.salt||\"\")===(user&&user.hash);\n  }\n  function cleanUsername(value){\n    const core=authCore();\n    if(core&&typeof core.cleanUsername===\"function\")return core.cleanUsername(value);\n    return String(value||\"\").trim();\n  }\n  function cleanText(value,max=200){\n    return String(value||\"\").trim().slice(0,max);\n  }\n  function cleanSubject(value){\n    return cleanText(value,80)||\"PMP\";\n  }\n  function cleanTags(value){\n    return String(value||\"\")\n      .split(/[,，、;；|]/)\n      .map(s=>s.trim())\n      .filter(Boolean)\n      .slice(0,12);\n  }\n  function roleLabel(role){\n    const api=window.KGRolePermissions;\n    return api&&typeof api.roleLabel===\"function\"?api.roleLabel(role):({admin:\"管理员\",teacher:\"教师/教研\",student:\"学员\",viewer:\"游客\"}[role]||role||\"学员\");\n  }\n  function statusLabel(status){\n    return ({active:\"正常\",paused:\"暂停\",archived:\"已归档\"}[status]||status||\"正常\");\n  }\n  function subscriptionApi(){\n    return window.KGSubscription || null;\n  }\n  let nativePayPollTimer=0;\n  function clearNativePayPolling(){\n    if(nativePayPollTimer){clearInterval(nativePayPollTimer);nativePayPollTimer=0;}\n  }\n  function setMembershipPaymentView(active){\n    const modal=document.querySelector(\"#userSubscriptionDetailModal .membership-ui\");\n    if(modal)modal.classList.toggle(\"is-payment-view\",!!active);\n  }\n  function renderSubscriptionBox(user){\n    const panel=$(\"ucSubscriptionBox\");\n    if(!panel)return;\n    panel.className=\"uc-info-card uc-membership-card\";\n    const sub=subscriptionApi();\n    if(!sub){\n      panel.innerHTML='<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-card-content\"><h3>订阅信息暂不可用</h3><p>请刷新页面后重试。</p></div>';\n      return;\n    }\n    const role=user&&user.role||\"student\";\n    if(role===\"admin\"||role===\"teacher\"){\n      panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>当前身份免订阅</h3><p>管理员和教师/教研不受学员订阅限制。</p></div></div><p class=\"uc-membership-note\">当前身份可直接使用系统管理或教学维护能力。</p></div>`;\n      return;\n    }\n    if(role===\"viewer\"){\n      panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div><div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>游客体验</h3><p>游客不进入订阅体系。</p></div></div><p class=\"uc-membership-note\">请登录或切换为学员账号后开通会员。</p></div>`;\n      return;\n    }\n    const summary=typeof sub.subscriptionSummary===\"function\"?sub.subscriptionSummary(user.username):null;\n    const plan=summary&&summary.plan || (sub.planById?sub.planById(\"free\"):{name:\"免费学员\"});\n    const record=summary&&summary.subscription || null;\n    const statusText=summary&&summary.statusText || \"有效\";\n    const expiresText=summary&&summary.expiresFullText || summary&&summary.expiresText || \"长期有效\";\n    const countdownText=summary&&summary.countdownText || \"长期有效\";\n    const hasActivePaidMembership=!!(record\n      && ACTIVE_PAID_MEMBERSHIP_STATUSES.has(record.status)\n      && plan\n      && plan.id\n      && plan.id!==\"free\");\n    const actionText=\"升级会员\";\n    panel.innerHTML=`<div class=\"uc-card-icon uc-card-icon-membership\">◇</div>\n      <div class=\"uc-membership-main\"><div class=\"uc-membership-heading\"><div><h3>${escapeHTML(plan.name||\"免费学员\")}</h3><p>${escapeHTML(plan.description||\"当前学员订阅状态。\")}</p></div>${hasActivePaidMembership?\"\":`<button type=\"button\" class=\"uc-button uc-button-primary uc-button-compact\" id=\"ucSubscriptionRenewBtn\">${escapeHTML(actionText)}</button>`}</div>\n      <div class=\"uc-meta-chips\"><span>✓ 状态：${escapeHTML(statusText)}</span><span>▣ 有效期：${escapeHTML(expiresText)}</span><span>◷ 倒计时：${escapeHTML(countdownText)}</span><span>◇ 来源：${escapeHTML(record&&record.source||\"default\")}</span></div>\n      <p class=\"uc-membership-note\">此处展示当前订阅状态和权益有效期。</p></div>`;\n    const btn=$(\"ucSubscriptionRenewBtn\");\n    if(btn)btn.addEventListener(\"click\",openSubscriptionDetailModal);\n  }\n  function renderWechatBox(user){\n    const panel=$(\"ucWechatBox\");\n    if(!panel)return;\n    panel.className=\"uc-info-card uc-binding-card\";\n    const wechat=user&&user.wechat;\n    const bound=!!(wechat&&wechat.bound);\n    const nickname=String(wechat&&wechat.nickname||\"微信用户\");\n    panel.innerHTML=bound\n      ?`<div class=\"uc-card-icon uc-card-icon-wechat\">◉</div><div class=\"uc-card-content\"><h3>微信已绑定</h3><p>已绑定微信账号：${escapeHTML(nickname)}。以后可直接使用微信扫码登录。</p></div><button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucWechatUnbindBtn\">解除绑定</button>`\n      :`<div class=\"uc-card-icon uc-card-icon-wechat\">◉</div><div class=\"uc-card-content\"><h3>尚未绑定微信</h3><p>绑定后可使用微信扫码登录当前账号。</p></div><button type=\"button\" class=\"uc-button uc-button-outline uc-button-compact\" id=\"ucWechatBindBtn\">绑定微信</button>`;\n    const bind=$(\"ucWechatBindBtn\");\n    const unbind=$(\"ucWechatUnbindBtn\");\n    if(bind)bind.addEventListener(\"click\",()=>{\n      const api=window.KGWechatLogin;\n      if(!api||typeof api.startOfficialLogin!==\"function\"){msg(\"微信登录模块未加载，请刷新后重试。\");return}\n      msg(\"正在跳转至微信授权页…\",true);\n      api.startOfficialLogin('bind');\n    });\n    if(unbind)unbind.addEventListener(\"click\",async()=>{\n      const api=window.KGWechatLogin;\n      if(!api||typeof api.unbind!==\"function\"){msg(\"微信登录模块未加载，请刷新后重试。\");return}\n      if(!confirm(\"解除后将不能使用该微信扫码登录，确定解除绑定吗？\"))return;\n      unbind.disabled=true;\n      const result=await api.unbind();\n      if(!result||!result.ok){\n        unbind.disabled=false;\n        msg(result&&result.message||\"解除微信绑定失败。\");\n        return;\n      }\n      fillForm();\n      msg(\"微信绑定已解除。\",true);\n      showStatus(\"微信绑定已解除。\");\n    });\n  }\n  function planFeatureList(plan){\n    const sub=subscriptionApi();\n    if(sub&&typeof sub.planBenefitItems===\"function\")return sub.planBenefitItems(plan);\n    const labels=sub&&sub.FEATURE_LABELS||{};\n    return Object.entries(plan&&plan.features||{}).filter(([,on])=>!!on).map(([key])=>labels[key]||key);\n  }\n  function planLimitText(plan){\n    const sub=subscriptionApi();\n    if(sub&&typeof sub.planUsageText===\"function\")return sub.planUsageText(plan);\n    const labels={dailyTraining:\"每日训练\",recallMaps:\"回忆图谱\",importPackages:\"学习包导入\",exportPackages:\"学习包导出\"};\n    return Object.entries(plan&&plan.limits||{}).map(([key,value])=>`${labels[key]||key}：${Number(value)===-1?\"不限\":String(value)}`).join(\" · \");\n  }\n  function ensureSubscriptionDetailModal(){\n    let modal=$(\"userSubscriptionDetailModal\");\n    if(modal)return modal;\n    const wrap=document.createElement(\"div\");\n    wrap.className=\"modal-backdrop user-subscription-detail-backdrop membership-ui-backdrop\";\n    wrap.id=\"userSubscriptionDetailModal\";\n    wrap.innerHTML=`\n      <div aria-labelledby=\"userSubscriptionDetailTitle\" aria-modal=\"true\" class=\"modal kg-subscription-detail-modal membership-ui\" role=\"dialog\">\n        <header class=\"modal-header\">\n          <div class=\"brand\">\n            <div class=\"brand-mark\" aria-hidden=\"true\">会</div>\n            <div>\n              <h2 class=\"brand-title\" id=\"userSubscriptionDetailTitle\">会员权益</h2>\n              <p class=\"brand-copy\">查看各会员方案权益，选择套餐后可使用微信扫码开通。</p>\n            </div>\n          </div>\n          <button class=\"icon-button dialog-close\" id=\"userSubscriptionDetailCloseBtn\" type=\"button\" aria-label=\"关闭\"><span class=\"modal-close-icon\" aria-hidden=\"true\"></span></button>\n        </header>\n        <div class=\"kg-subscription-detail-body\" id=\"userSubscriptionDetailBody\"></div>\n      </div>`;\n    document.body.appendChild(wrap);\n    wrap.addEventListener(\"click\",event=>{if(event.target===wrap)closeSubscriptionDetailModal()});\n    $(\"userSubscriptionDetailCloseBtn\").addEventListener(\"click\",closeSubscriptionDetailModal);\n    return wrap;\n  }\n  function renderSubscriptionDetailPlans(){\n    setMembershipPaymentView(false);\n    const body=$(\"userSubscriptionDetailBody\");\n    const sub=subscriptionApi();\n    const rec=currentRecord();\n    if(!body||!sub){return}\n    const summary=rec&&typeof sub.subscriptionSummary===\"function\"?sub.subscriptionSummary(rec.username):null;\n    const currentPlanId=summary&&summary.plan&&summary.plan.id || \"\";\n    const plans=typeof sub.enabledPlanList===\"function\"?sub.enabledPlanList():[];\n    let activeNativeOrder=null;\n    let planPickLocked=false;\n    function setPlanPickLocked(locked){\n      planPickLocked=!!locked;\n      body.querySelectorAll('[data-buy-plan]').forEach(button=>{\n        const isActive=activeNativeOrder&&button.dataset.buyPlan===String(activeNativeOrder.planId||\"\");\n        button.disabled=planPickLocked&&!isActive;\n        button.setAttribute(\"aria-disabled\",String(planPickLocked&&!isActive));\n      });\n    }\n    body.innerHTML=`<div class=\"divider\"></div><div class=\"plans-grid\">\n      ${plans.map(plan=>{\n        const current=!!currentPlanId && plan.id===currentPlanId;\n        const features=planFeatureList(plan);\n        const limitText=planLimitText(plan);\n        const featured=plan.id===\"monthly\"||!!plan.recommended;\n        const canPurchase=!current && plan.id!==\"free\";\n        const cta=current?(plan.id===\"free\"?\"当前使用中\":\"当前方案\"):(plan.id===\"free\"?\"免费使用\":\"选择该方案\");\n        return `<article class=\"plan-card${featured?' featured':''}${current?' current':''}\" data-plan-id=\"${escapeHTML(plan.id)}\">\n          <div class=\"plan-head\">\n            <h3 class=\"plan-title\">${escapeHTML(plan.name||'套餐')}</h3>\n            <span class=\"pill${plan.recommended&&!current?' pill-warning':''}\">${plan.recommended&&!current?'<span class=\"icon i-star\"></span>':''}${escapeHTML(current?'当前方案':(plan.badgeText||plan.shortName||'套餐'))}</span>\n          </div>\n          <div class=\"plan-price\">\n            <strong>${escapeHTML(plan.priceText||'待配置')}</strong>\n            ${plan.originalPriceText?`<del>${escapeHTML(plan.originalPriceText)}</del>`:''}\n          </div>\n          <p class=\"plan-desc\">${escapeHTML(plan.description||'')}</p>\n          <div class=\"plan-rule\"></div>\n          <div class=\"benefit-line\"><span class=\"benefit-dot\"></span><span>${escapeHTML(features[0]||'会员权益')}</span></div>\n          ${limitText?`<div class=\"feature-chip\"><span class=\"icon i-infinity\"></span><span>${escapeHTML(limitText)}</span></div>`:''}\n          <button type=\"button\" class=\"btn ${current?'current-btn':'btn-primary'}\"${canPurchase?` data-buy-plan=\"${escapeHTML(plan.id)}\"`:\" disabled\"}>${current?'<span class=\"icon i-check-circle\"></span>':''}${escapeHTML(cta)}${canPurchase?'<span class=\"icon i-chevron-right\"></span>':''}</button>\n        </article>`;\n      }).join('')}\n    </div>\n    <section class=\"membership-checkout\" id=\"membershipCheckout\" hidden aria-live=\"polite\"></section>\n    <section class=\"redeem\">\n      <div class=\"redeem-intro\">\n        <div class=\"redeem-icon\"><span class=\"icon i-ticket\"></span></div>\n        <div><h3 class=\"redeem-title\">卡密使用</h3><p class=\"redeem-copy\">使用会员卡密兑换会员权益</p></div>\n      </div>\n      <input class=\"redeem-input\" id=\"subscriptionRedeemCodeInput\" placeholder=\"请输入会员卡密，例如 VIP-XXXX-XXXX-XXXX\" autocomplete=\"off\" />\n      <button type=\"button\" class=\"btn btn-primary\" id=\"subscriptionRedeemCodeBtn\">兑换卡密</button>\n      <div class=\"redeem-message\" id=\"subscriptionRedeemCodeMsg\"></div>\n    </section>\n    <div class=\"footnote\"><span class=\"icon i-shield-check\"></span>卡密兑换成功后，权益将自动开通并即时生效</div>`;\n    function renderNativePayment(plan,order){\n      const pay=window.KGWechatPay;\n      if(!body||!pay||!order||!order.id)return;\n      clearNativePayPolling();\n      // 二维码已生成后解锁套餐按钮：点击其他套餐会重新下单（服务端自动作废旧\n      // 待支付订单），点击同一套餐则继续展示当前二维码。\n      setPlanPickLocked(false);\n      setMembershipPaymentView(true);\n      const amountFen=Math.max(0,Number(order.amount)||0);\n      const amount=`￥${amountFen%100===0?String(amountFen/100):(amountFen/100).toFixed(2)}`;\n      body.querySelectorAll(\".plan-card[data-plan-id]\").forEach(card=>card.classList.toggle(\"checkout-selected\",card.dataset.planId===String(plan&&plan.id||order.planId||\"\")));\n      const checkout=$(\"membershipCheckout\");\n      if(!checkout)return;\n      checkout.hidden=false;\n      checkout.innerHTML=`<div class=\"checkout-qr\"><div class=\"payment-tag\"><span class=\"icon i-wechat\"></span>微信扫码支付</div><div class=\"qr-frame\"><img class=\"kg-native-pay-qr\" src=\"${escapeHTML(pay.nativeOrderQrCodeUrl(order.id))}\" alt=\"微信支付二维码\" /></div></div>\n        <div class=\"checkout-summary\"><div><p class=\"summary-label\">正在开通</p><h3 class=\"checkout-plan-name\">${escapeHTML(plan&&plan.name||order.planName||'会员方案')}</h3><p class=\"checkout-help\">请使用微信扫描二维码完成付款，支付结果会自动刷新。</p></div><div class=\"checkout-amount\"><span>应付金额</span><strong>${escapeHTML(amount)}</strong></div><div class=\"checkout-meta\"><span>订单编号：${escapeHTML(order.id)}</span><span id=\"nativePayStatus\">等待扫码付款</span></div></div>\n        `;\n      const status=$(\"nativePayStatus\");\n      const refresh=async()=>{\n        try{\n          const latest=await pay.getNativeOrderStatus(order.id);\n          if(latest.payStatus===\"paid\"){\n            clearNativePayPolling();\n            pay.syncSubscription(latest.subscription);\n            renderOrderSubmitted(plan,{order});\n            showStatus(\"支付成功，会员权益已开通。\",true);\n            window.setTimeout(()=>{\n              closeSubscriptionDetailModal();\n              window.location.href=\"index.html?mode=free\";\n            },1600);\n            return;\n          }\n          if(status)status.textContent=\"等待扫码付款\";\n        }catch(error){\n          if(status)status.textContent=\"支付状态同步失败，正在自动重试\";\n        }\n      };\n      nativePayPollTimer=setInterval(refresh,3000);\n      refresh();\n    }\n    function renderOrderSubmitted(plan,result){\n      setMembershipPaymentView(false);\n      const order=result&&result.order||{};\n      body.innerHTML=`<div class=\"divider\"></div><section class=\"payment-success\"><div class=\"success-icon\"><span class=\"icon i-check-circle\"></span></div><h3>支付成功</h3><p>会员权益已开通，即将返回首页。</p><div class=\"success-meta\"><span>开通方案：${escapeHTML(plan&&plan.name||order.planName||'会员')}</span><span>订单编号：${escapeHTML(order.id||'—')}</span></div><button type=\"button\" class=\"btn btn-primary\" id=\"subscriptionCloseAfterSubmitBtn\">知道了</button></section>`;\n      $(\"subscriptionCloseAfterSubmitBtn\")?.addEventListener(\"click\",closeSubscriptionDetailModal);\n    }\n    function requestAuthenticationForPlan(plan){\n      closeSubscriptionDetailModal();\n      const reason=`登录后即可开通${plan&&plan.name||'会员方案'}。`;\n      showStatus(reason);\n      if(typeof window.authOpen===\"function\"){window.authOpen(reason);return}\n      $(\"authLoginBtn\")?.click();\n    }\n    async function handlePlanPick(card){\n      const planId=card&&card.dataset.buyPlan;\n      if(!planId)return;\n      const plan=sub.planById?sub.planById(planId):null;\n      if(planPickLocked)return; // 正在生成支付二维码，防止连点重复下单\n      if(activeNativeOrder&&activeNativeOrder.planId===planId){renderNativePayment(plan,activeNativeOrder);return}\n      const latest=currentRecord();\n      const role=latest&&latest.user&&latest.user.role || \"guest\";\n      if(!latest){\n        requestAuthenticationForPlan(plan);\n        return;\n      }\n      if(role===\"admin\"||role===\"teacher\"){\n        showStatus(\"当前身份不需要订阅，可直接使用管理或教学能力。\");\n        return;\n      }\n      if(role===\"viewer\"){\n        requestAuthenticationForPlan(plan);\n        return;\n      }\n      if(plan&&plan.id===\"free\"){\n        showStatus(\"免费学员无需购买，可直接使用免费权益。\");\n        return;\n      }\n      const pay=window.KGWechatPay;\n      if(!pay||typeof pay.createNativeOrder!==\"function\"){\n        showStatus(\"支付服务不可用，请刷新页面后重试。\");\n        return;\n      }\n      const originalLabel=card.innerHTML;\n      setPlanPickLocked(true);\n      card.textContent=\"正在生成支付二维码…\";\n      try{\n        if(activeNativeOrder&&activeNativeOrder.planId===plan.id){\n          card.innerHTML=originalLabel;\n          renderNativePayment(plan,activeNativeOrder);\n          return;\n        }\n        const result=await pay.createNativeOrder(plan.id);\n        if(!result||!result.order||!result.order.codeUrl)throw new Error(\"支付二维码生成失败，请重试。\");\n        // 服务端不复用待支付订单：每次点击都按当前所选套餐重新下单，\n        // 并自动作废旧待支付订单（点击哪个套餐就显示哪个套餐）。\n        const order=result.order;\n        const checkoutPlan=sub.planById?sub.planById(order.planId):null;\n        activeNativeOrder={...order,planId:order.planId||plan.id};\n        card.innerHTML=originalLabel;\n        renderNativePayment(checkoutPlan||plan,order);\n        showStatus(\"支付二维码已生成，请使用微信扫码。\");\n      }catch(error){\n        showStatus(String(error&&error.message||\"支付二维码生成失败，请重试。\"));\n        setPlanPickLocked(false);\n        card.innerHTML=originalLabel;\n      }\n    }\n    body.querySelectorAll('[data-buy-plan]').forEach(card=>card.addEventListener('click',()=>handlePlanPick(card)));\n    const redeemBtn=$(\"subscriptionRedeemCodeBtn\");\n    const redeemInput=$(\"subscriptionRedeemCodeInput\");\n    const redeemMsg=$(\"subscriptionRedeemCodeMsg\");\n    function setRedeemMsg(text,ok){\n      if(!redeemMsg)return;\n      redeemMsg.textContent=text||\"\";\n      redeemMsg.classList.toggle(\"ok\",!!ok);\n    }\n    if(redeemBtn&&redeemInput){\n      const submitRedeem=()=>{\n        const api=subscriptionApi();\n        if(!api||typeof api.redeemCode!==\"function\"){setRedeemMsg(\"卡密模块未加载，请刷新页面后重试。\",false);return}\n        const result=api.redeemCode(redeemInput.value);\n        setRedeemMsg(result&&result.message||\"卡密兑换失败。\",!!(result&&result.ok));\n        showStatus(result&&result.message||\"卡密兑换失败。\");\n        if(result&&result.ok){\n          redeemInput.value=\"\";\n          refreshAuthUI();\n          setTimeout(renderSubscriptionDetailPlans,600);\n        }\n      };\n      redeemBtn.addEventListener(\"click\",submitRedeem);\n      redeemInput.addEventListener(\"keydown\",event=>{\n        if(event.key===\"Enter\"){event.preventDefault();submitRedeem()}\n      });\n    }\n  }\n  function openSubscriptionDetailModal(){\n    const userCenter=$(\"userCenterModal\");\n    if(userCenter&&userCenter.classList.contains(\"show\"))userCenter.classList.remove(\"show\");\n    const modal=ensureSubscriptionDetailModal();\n    setMembershipPaymentView(false);\n    renderSubscriptionDetailPlans();\n    modal.classList.add(\"show\");\n  }\n  function closeSubscriptionDetailModal(){\n    clearNativePayPolling();\n    setMembershipPaymentView(false);\n    const modal=$(\"userSubscriptionDetailModal\");\n    if(modal)modal.classList.remove(\"show\");\n  }\n\n  function currentUsername(){\n    const core=authCore();\n    if(core&&typeof core.currentUsername===\"function\")return core.currentUsername();\n    try{return cleanUsername(Store.readString?Store.readString(AUTH_SESSION_KEY,\"\"):localStorage.getItem(AUTH_SESSION_KEY)||\"\")}catch(e){return \"\"}\n  }\n  function users(){\n    const core=authCore();\n    if(core&&typeof core.users===\"function\")return core.users();\n    return readJSON(AUTH_USERS_KEY,{}) || {};\n  }\n  function saveUser(username,patch){\n    const core=authCore();\n    if(core&&typeof core.upsertUser===\"function\")return core.upsertUser(username,patch);\n    const map=users();\n    map[username]={...(map[username]||{}),...patch,username,updatedAt:Date.now()};\n    writeJSON(AUTH_USERS_KEY,map);\n    window.dispatchEvent(new CustomEvent(\"kg-auth-users-change\",{detail:{username,user:map[username]}}));\n    return map[username];\n  }\n  function currentRecord(){\n    const username=currentUsername();\n    if(!username)return null;\n    const core=authCore();\n    const coreUser=core&&typeof core.currentUser===\"function\"?core.currentUser({includeInactive:true}):null;\n    if(coreUser)return {username,user:{...coreUser}};\n    const map=users();\n    const user=map[username];\n    if(!user||typeof user!==\"object\")return null;\n    return {username,user:{...user}};\n  }\n  function logAction(action,username,detail=\"\"){\n    const core=authCore();\n    if(core&&typeof core.logAction===\"function\")return core.logAction(action,username,detail);\n    try{\n      const logs=readJSON(USER_LOG_KEY,[]);\n      logs.unshift({id:Math.random().toString(36).slice(2),action,username,detail:String(detail||\"\"),actor:username||\"self\",at:Date.now()});\n      writeJSON(USER_LOG_KEY,logs.slice(0,300));\n    }catch(e){}\n  }\n  function showStatus(message){\n    if(typeof window.showStatus===\"function\")window.showStatus(message);\n    else{\n      const status=$(\"status\");\n      if(status){\n        status.textContent=message;\n        status.classList.add(\"show\");\n        clearTimeout(showStatus.timer);\n        showStatus.timer=setTimeout(()=>status.classList.remove(\"show\"),2200);\n      }\n    }\n  }\n  function refreshAuthUI(){\n    const api=window.KGRolePermissions;\n    if(api){\n      if(typeof api.applyTheme===\"function\")api.applyTheme();\n      const status=$(\"authStatus\");\n      if(status&&typeof api.renderStatus===\"function\")api.renderStatus(status);\n      if(typeof api.decoratePermissionElements===\"function\")api.decoratePermissionElements();\n    }\n    if(typeof window.authRenderStatus===\"function\")window.authRenderStatus();\n    if(window.KGSubscription&&typeof window.KGSubscription.decorateSubscriptionElements===\"function\")window.KGSubscription.decorateSubscriptionElements();\n    if(window.KGGlobalShortcuts&&typeof window.KGGlobalShortcuts.render===\"function\")window.KGGlobalShortcuts.render();\n    window.dispatchEvent(new CustomEvent(\"kg-user-profile-updated\",{detail:{username:currentUsername()}}));\n    window.dispatchEvent(new CustomEvent(\"kg-role-theme-change\",{detail:{role:api&&api.currentRole?api.currentRole():\"\"}}));\n  }\n  function ensureModal(){\n    let modal=$(\"userCenterModal\");\n    if(modal)return modal;\n    const wrap=document.createElement(\"div\");\n    wrap.className=\"modal-backdrop user-center-backdrop\";\n    wrap.id=\"userCenterModal\";\n    wrap.innerHTML=`\n      <div aria-labelledby=\"userCenterTitle\" aria-modal=\"true\" class=\"modal kg-user-center-modal uc-dialog\" role=\"dialog\">\n        <header class=\"uc-header\"><div class=\"uc-profile-heading\"><div class=\"uc-avatar\" id=\"userCenterAvatar\">我</div><div><h2 id=\"userCenterTitle\">用户中心</h2><p>维护自己的账号资料。角色和账号状态由管理员统一调整。</p></div></div><button class=\"uc-close dialog-close\" id=\"userCenterCloseBtn\" type=\"button\" aria-label=\"关闭用户中心\"><span class=\"modal-close-icon\" aria-hidden=\"true\"></span></button></header>\n        <div class=\"kg-user-center-body uc-body\"><div class=\"uc-form-grid\">\n          <label class=\"uc-field uc-field-readonly\"><span>用户名</span><div><input id=\"ucUsername\" readonly /><b aria-hidden=\"true\">♙</b></div></label>\n          <label class=\"uc-field\"><span>显示名称</span><div><input id=\"ucDisplayName\" maxlength=\"40\" placeholder=\"例如：Alex / 张老师\" /></div></label>\n          <label class=\"uc-field\"><span>邮箱</span><div><input id=\"ucEmail\" maxlength=\"120\" placeholder=\"name@example.com\" /></div></label>\n          <label class=\"uc-field\"><span>手机 / 联系方式</span><div><input id=\"ucPhone\" maxlength=\"40\" placeholder=\"可选\" /></div></label>\n          <label class=\"uc-field\"><span>主要科目</span><div><input id=\"ucSubject\" maxlength=\"80\" placeholder=\"PMP / ACP / CSPM\" /></div></label>\n          <label class=\"uc-field\"><span>标签</span><div><input id=\"ucTags\" maxlength=\"160\" placeholder=\"多个标签用逗号分隔\" /></div></label>\n        </div>\n        <div class=\"uc-status-row\"><span class=\"uc-status-chip uc-role\" id=\"ucRoleChip\">角色：—</span><span class=\"uc-status-chip uc-normal\" id=\"ucStatusChip\">状态：—</span></div>\n        <section class=\"uc-info-card uc-binding-card\" id=\"ucWechatBox\" aria-label=\"微信登录\"></section>\n        <section class=\"uc-info-card uc-membership-card\" id=\"ucSubscriptionBox\" aria-label=\"我的订阅\"></section>\n        <label class=\"uc-field uc-notes-field\"><span>个人备注 / 学习说明</span><div class=\"uc-textarea-wrap\"><textarea id=\"ucNote\" maxlength=\"500\" placeholder=\"例如：所在班级、学习目标、备考进度等，保存后会同步到服务器。\"></textarea><em id=\"ucNoteCount\">0/500</em></div></label>\n        <section class=\"uc-password-card\"><h3>安全设置 · 修改密码（可选）</h3><p>不修改密码时请留空；微信账号或未设置密码的账号可直接设置新密码。</p><div class=\"uc-form-grid uc-password-grid\"><label class=\"uc-field\"><span>当前密码</span><div><input id=\"ucCurrentPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"修改密码时填写\" /></div></label><label class=\"uc-field\"><span>新密码</span><div><input id=\"ucNewPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"至少 4 位\" /></div></label><label class=\"uc-field\"><span>确认新密码</span><div><input id=\"ucConfirmPassword\" type=\"password\" autocomplete=\"new-password\" placeholder=\"再次输入新密码\" /></div></label></div></section>\n        </div>\n        <footer class=\"kg-user-center-footer\" data-uc-footer><div class=\"kg-user-center-msg uc-message\" id=\"userCenterMsg\"></div><div class=\"uc-actions\"><button class=\"uc-button uc-button-secondary\" id=\"userCenterCancelBtn\" type=\"button\">取消</button><button class=\"uc-button uc-button-primary\" id=\"userCenterSaveBtn\" type=\"button\">保存个人资料</button></div></footer>\n      </div>`;\n    document.body.appendChild(wrap);\n    wrap.addEventListener(\"click\",event=>{if(event.target===wrap)closeModal()});\n    $(\"userCenterCloseBtn\").addEventListener(\"click\",closeModal);\n    $(\"userCenterCancelBtn\").addEventListener(\"click\",closeModal);\n    $(\"userCenterSaveBtn\").addEventListener(\"click\",saveProfile);\n    $(\"ucNote\").addEventListener(\"input\",()=>{\n      const count=$(\"ucNoteCount\");\n      if(count)count.textContent=`${$(\"ucNote\").value.length}/500`;\n    });\n    document.addEventListener(\"keydown\",event=>{\n      if(event.key===\"Escape\"){\n        if($(\"userSubscriptionDetailModal\")&&$(\"userSubscriptionDetailModal\").classList.contains(\"show\"))closeSubscriptionDetailModal();\n        else if(wrap.classList.contains(\"show\"))closeModal();\n      }\n    });\n    return wrap;\n  }\n  function msg(text,ok=false){\n    const el=$(\"userCenterMsg\");\n    if(!el)return;\n    el.textContent=text||\"\";\n    el.classList.toggle(\"ok\",!!ok);\n  }\n  function fillForm(){\n    const rec=currentRecord();\n    if(!rec)return false;\n    const {username,user}=rec;\n    $(\"ucUsername\").value=username;\n    $(\"ucDisplayName\").value=user.displayName||username;\n    $(\"ucEmail\").value=user.email||\"\";\n    $(\"ucPhone\").value=user.phone||\"\";\n    $(\"ucSubject\").value=user.subject||\"PMP\";\n    $(\"ucTags\").value=Array.isArray(user.tags)?user.tags.join(\"，\"):String(user.tags||\"\");\n    $(\"ucNote\").value=user.note||\"\";\n    $(\"ucNoteCount\").textContent=`${$(\"ucNote\").value.length}/500`;\n    $(\"ucRoleChip\").textContent=\"角色：\"+roleLabel(user.role||\"student\");\n    $(\"ucStatusChip\").textContent=\"状态：\"+statusLabel(user.status||\"active\");\n    renderWechatBox(user);\n    renderSubscriptionBox(user);\n    $(\"ucCurrentPassword\").value=\"\";\n    $(\"ucNewPassword\").value=\"\";\n    $(\"ucConfirmPassword\").value=\"\";\n    const avatar=$(\"userCenterAvatar\");\n    const name=String(user.displayName||username||\"我\").trim();\n    avatar.textContent=name.slice(0,1).toUpperCase()||\"我\";\n    msg(\"\");\n    return true;\n  }\n  function openModal(){\n    const modal=ensureModal();\n    const rec=currentRecord();\n    if(!rec){\n      const login=$(\"authLoginBtn\");\n      if(login){\n        login.click();\n        showStatus(\"请先登录后再进入用户中心。\");\n      }else{\n        alert(\"请先登录后再进入用户中心。\");\n      }\n      return;\n    }\n    if(!fillForm())return;\n    modal.classList.add(\"show\");\n    setTimeout(()=>$(\"ucDisplayName\")&&$(\"ucDisplayName\").focus(),80);\n  }\n  function closeModal(){\n    const modal=$(\"userCenterModal\");\n    if(modal)modal.classList.remove(\"show\");\n  }\n  async function saveProfile(){\n    const rec=currentRecord();\n    if(!rec){msg(\"请先登录。\");return}\n    const {username,user}=rec;\n    const displayName=cleanText($(\"ucDisplayName\").value,40)||username;\n    const email=cleanText($(\"ucEmail\").value,120);\n    const phone=cleanText($(\"ucPhone\").value,40);\n    const subject=cleanSubject($(\"ucSubject\").value);\n    const tags=cleanTags($(\"ucTags\").value);\n    const note=cleanText($(\"ucNote\").value,500);\n    const currentPassword=String($(\"ucCurrentPassword\").value||\"\");\n    const newPassword=String($(\"ucNewPassword\").value||\"\");\n    const confirmPassword=String($(\"ucConfirmPassword\").value||\"\");\n\n    if(email && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)){\n      msg(\"邮箱格式不正确。\");\n      return;\n    }\n    if(newPassword||confirmPassword||currentPassword){\n      if(newPassword.length<4){\n        msg(\"新密码至少 4 位。\");\n        return;\n      }\n      if(newPassword!==confirmPassword){\n        msg(\"两次输入的新密码不一致。\");\n        return;\n      }\n      if(user.hash){\n        const ok=verifyPassword(username,currentPassword,user);\n        if(!ok){\n          msg(\"当前密码不正确。\");\n          return;\n        }\n      }\n      const salt=makeSalt();\n      user.salt=salt;\n      user.hash=passwordHash(username,newPassword,salt);\n    }\n\n    const patch={\n      ...user,\n      displayName,\n      email,\n      phone,\n      subject,\n      tags,\n      note,\n      updatedAt:Date.now()\n    };\n    const core=authCore();\n    const saveBtn=$(\"userCenterSaveBtn\");if(saveBtn)saveBtn.disabled=true;\n    try{\n      if(core?.providerStatus?.().remote&&typeof core.updateProfile===\"function\"){\n        const result=await core.updateProfile({...patch,currentPassword,newPassword});\n        if(!result?.ok){msg(result?.message||\"个人资料保存失败，请稍后重试。\");return}\n      }else saveUser(username,patch);\n    }finally{if(saveBtn)saveBtn.disabled=false}\n    logAction(\"用户自助更新资料\",username,newPassword?\"更新资料并修改密码\":\"更新资料\");\n    refreshAuthUI();\n    fillForm();\n    msg(\"个人资料已保存。\",true);\n    showStatus(\"个人资料已更新。\");\n    setTimeout(closeModal,650);\n  }\n  function bindEntry(){\n    const status=$(\"authStatus\");\n    if(!status)return;\n    if(String(status.dataset.accountMenuTrigger||\"\").toLowerCase()===\"true\"){\n      // 首页账号胶囊由 KGAccountMenu 统一接管；避免点击后直接弹出用户中心。\n      status.dataset.userCenterEntry=\"account-menu\";\n      return;\n    }\n    if(status.dataset.userCenterBound===\"1\")return;\n    status.dataset.userCenterBound=\"1\";\n    status.setAttribute(\"role\",\"button\");\n    status.setAttribute(\"tabindex\",\"0\");\n    status.setAttribute(\"title\",\"点击打开用户中心\");\n    status.addEventListener(\"click\",event=>{\n      event.preventDefault();\n      openModal();\n    });\n    status.addEventListener(\"keydown\",event=>{\n      if(event.key===\"Enter\"||event.key===\" \"){\n        event.preventDefault();\n        openModal();\n      }\n    });\n  }\n  function bindSubscriptionEntrypoints(){\n    document.querySelectorAll(\"#upgradeMemberBtn,[data-open-subscription-detail]\").forEach(btn=>{\n      if(!btn || btn.dataset.subscriptionDetailBound===\"1\")return;\n      btn.dataset.subscriptionDetailBound=\"1\";\n      btn.addEventListener(\"click\",event=>{\n        event.preventDefault();\n        openSubscriptionDetailModal();\n      });\n    });\n  }\n  function init(){\n    bindEntry();\n    bindSubscriptionEntrypoints();\n    ensureModal();\n    window.addEventListener(\"kg-user-profile-updated\",()=>setTimeout(()=>{bindEntry();bindSubscriptionEntrypoints()},0));\n    window.addEventListener(\"kg-subscription-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    window.addEventListener(\"kg-subscription-plan-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    window.addEventListener(\"kg-wechat-binding-change\",()=>{if($(\"userCenterModal\")&&$(\"userCenterModal\").classList.contains(\"show\"))fillForm()});\n    window.addEventListener(\"storage\",event=>{\n      if(!event.key || event.key===AUTH_USERS_KEY || event.key===AUTH_SESSION_KEY){\n        setTimeout(()=>{bindEntry();refreshAuthUI()},0);\n      }\n    });\n  }\n  if(document.readyState===\"loading\")document.addEventListener(\"DOMContentLoaded\",init);\n  else init();\n  window.KGUserCenter={open:openModal,refresh:refreshAuthUI,openSubscriptionDetail:openSubscriptionDetailModal,closeSubscriptionDetail:closeSubscriptionDetailModal};\n})();\n//# sourceURL=src/33-user-center.js"],["src/101-engagement-repository.js","'use strict';\n\n/*\n * 用户帮助、需求反馈与站内消息统一仓库。\n *\n * 浏览器页面通过 KG_APP_CONFIG.engagement 连接认证后的服务端 REST 接口。\n */\n(function(global){\n  const FEEDBACK_KEY='kg_user_feedback_v1';\n  const ANNOUNCEMENT_KEY='kg_announcements_v1';\n  const READ_KEY_PREFIX='kg_user_message_reads_v1__';\n  const FEEDBACK_READ_KEY_PREFIX='kg_user_feedback_reply_reads_v1__';\n  const EVENT_NAME='kg-engagement-change';\n  const FEEDBACK_STATUSES=Object.freeze(['pending','in_progress','resolved','closed']);\n  const MESSAGE_STATUSES=Object.freeze(['draft','published','withdrawn']);\n\n  function clone(value){if(value===undefined)return undefined;try{return JSON.parse(JSON.stringify(value))}catch(error){return value}}\n  function text(value){return String(value==null?'':value).trim()}\n  function number(value,fallback=0){const result=Number(value);return Number.isFinite(result)?result:fallback}\n  function uid(prefix='item'){return prefix+'-'+(global.crypto?.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now().toString(36))}\n  function readJson(key,fallback){try{const raw=global.localStorage?.getItem(key);if(!raw)return clone(fallback);const value=JSON.parse(raw);return value==null?clone(fallback):value}catch(error){return clone(fallback)}}\n  function writeJson(key,value){try{global.localStorage?.setItem(key,JSON.stringify(value));if(typeof global.CustomEvent==='function')global.dispatchEvent?.(new global.CustomEvent(EVENT_NAME,{detail:{key}}));return true}catch(error){console.warn('[KGEngagementRepository] write failed',key,error);return false}}\n  function currentUser(){\n    const user=global.KGAuthCore?.currentUser?.({includeInactive:true})||global.KGRolePermissions?.currentUser?.()||null;\n    if(user)return {username:text(user.username||user.id),displayName:text(user.displayName||user.name||user.username),role:text(user.role||'student')||'student'};\n    return {username:'guest',displayName:'游客',role:'viewer'};\n  }\n  function currentUserId(){return currentUser().username||'guest'}\n  function config(){\n    const raw=global.KG_APP_CONFIG?.engagement||global.KG_ENGAGEMENT_CONFIG||{};\n    const mode=text(raw.mode||'local-demo').toLowerCase()==='remote'?'remote':'local-demo';\n    return {\n      mode,\n      baseUrl:text(raw.baseUrl||'').replace(/\\/$/,''),\n      credentials:text(raw.credentials||'include')||'include',\n      endpoints:{\n        submitFeedback:text(raw.endpoints?.submitFeedback||'/api/feedback'),\n        myFeedback:text(raw.endpoints?.myFeedback||'/api/feedback/mine'),\n        adminFeedback:text(raw.endpoints?.adminFeedback||'/api/admin/feedback'),\n        messages:text(raw.endpoints?.messages||'/api/messages'),\n        adminMessages:text(raw.endpoints?.adminMessages||'/api/admin/messages'),\n        markMessageRead:text(raw.endpoints?.markMessageRead||'/api/messages/{id}/read'),\n        markAllRead:text(raw.endpoints?.markAllRead||'/api/messages/read-all'),\n        markFeedbackRead:text(raw.endpoints?.markFeedbackRead||'/api/feedback/{id}/read'),\n        unreadSummary:text(raw.endpoints?.unreadSummary||'/api/engagement/unread-summary')\n      }\n    };\n  }\n  function endpoint(path){const cfg=config();if(/^https?:\\/\\//i.test(path))return path;return cfg.baseUrl+(path.startsWith('/')?path:'/'+path)}\n  function pagedEndpoint(path,options={}){\n    const limit=Math.max(1,Math.min(200,Math.floor(number(options.limit,200))));\n    const offset=Math.max(0,Math.floor(number(options.offset,0)));\n    return path+(path.includes('?')?'&':'?')+'limit='+limit+'&offset='+offset;\n  }\n  async function remoteRequest(path,options={}){\n    const cfg=config();\n    const response=await fetch(endpoint(path),{\n      method:options.method||'GET',credentials:cfg.credentials,\n      headers:{'Content-Type':'application/json',...(options.headers||{})},\n      body:options.body===undefined?undefined:JSON.stringify(options.body)\n    });\n    let payload=null;try{payload=await response.json()}catch(error){}\n    if(!response.ok)throw new Error(text(payload?.detail||payload?.message||payload?.error||('服务请求失败（'+response.status+'）')));\n    return payload;\n  }\n  async function remoteAllPages(path){\n    const rows=[];let offset=0;\n    while(rows.length<1000){\n      const payload=await remoteRequest(pagedEndpoint(path,{limit:200,offset}));\n      const page=Array.isArray(payload)?payload:(payload?.items||[]);\n      rows.push(...page);\n      if(Array.isArray(payload)||!payload?.pagination?.hasMore||!page.length)break;\n      const next=number(payload.pagination.offset,offset)+number(payload.pagination.limit,page.length);\n      if(next<=offset)break;offset=next;\n    }\n    return rows.slice(0,1000);\n  }\n  function normalizeFeedback(item,index=0){\n    item=item&&typeof item==='object'?item:{};\n    const actor=item.submittedBy&&typeof item.submittedBy==='object'?item.submittedBy:{};\n    return {\n      id:text(item.id)||('feedback-'+index),type:text(item.type||'suggestion')||'suggestion',title:text(item.title),detail:text(item.detail),\n      page:text(item.page),appVersion:text(item.appVersion),contact:text(item.contact),attachment:item.attachment&&typeof item.attachment==='object'?clone(item.attachment):null,\n      status:FEEDBACK_STATUSES.includes(text(item.status))?text(item.status):'pending',\n      submittedBy:{username:text(actor.username||item.username||'guest')||'guest',displayName:text(actor.displayName||actor.username||'游客'),role:text(actor.role||'viewer')||'viewer'},\n      createdAt:number(item.createdAt,Date.now()),updatedAt:number(item.updatedAt||item.createdAt,Date.now()),\n      lastReadAt:number(item.lastReadAt||item.userLastReadAt,0),\n      unreadReplyCount:Math.max(0,Math.floor(number(item.unreadReplyCount,0))),\n      replies:(Array.isArray(item.replies)?item.replies:[]).map((reply,replyIndex)=>({id:text(reply?.id)||('reply-'+replyIndex),message:text(reply?.message),actor:text(reply?.actor||'管理员'),createdAt:number(reply?.createdAt,Date.now())})).filter(reply=>reply.message)\n    };\n  }\n  function normalizeAudience(value){\n    value=value&&typeof value==='object'?value:{};\n    const type=['all','roles','users'].includes(text(value.type))?text(value.type):'all';\n    return {type,roles:[...new Set((Array.isArray(value.roles)?value.roles:[]).map(text).filter(Boolean))],users:[...new Set((Array.isArray(value.users)?value.users:[]).map(text).filter(Boolean))]};\n  }\n  function normalizeAnnouncement(item,index=0){\n    item=item&&typeof item==='object'?item:{};\n    return {\n      id:text(item.id)||('message-'+index),title:text(item.title),body:text(item.body),link:text(item.link),\n      status:MESSAGE_STATUSES.includes(text(item.status))?text(item.status):'draft',audience:normalizeAudience(item.audience),\n      publishAt:number(item.publishAt||item.publishedAt,0),expiresAt:number(item.expiresAt,0),publishedAt:number(item.publishedAt,0),withdrawnAt:number(item.withdrawnAt,0),\n      createdBy:text(item.createdBy||'system-admin'),createdAt:number(item.createdAt,Date.now()),updatedAt:number(item.updatedAt||item.createdAt,Date.now())\n    };\n  }\n  function localFeedback(){const rows=readJson(FEEDBACK_KEY,[]);return (Array.isArray(rows)?rows:[]).map(normalizeFeedback)}\n  function saveLocalFeedback(rows){return writeJson(FEEDBACK_KEY,rows.map(normalizeFeedback))}\n  function localAnnouncements(){const rows=readJson(ANNOUNCEMENT_KEY,[]);return (Array.isArray(rows)?rows:[]).map(normalizeAnnouncement)}\n  function saveLocalAnnouncements(rows){return writeJson(ANNOUNCEMENT_KEY,rows.map(normalizeAnnouncement))}\n  function readKey(userId=currentUserId()){return READ_KEY_PREFIX+encodeURIComponent(text(userId)||'guest')}\n  function localReads(userId=currentUserId()){const value=readJson(readKey(userId),{});return value&&typeof value==='object'?value:{}}\n  function saveLocalReads(value,userId=currentUserId()){return writeJson(readKey(userId),value||{})}\n  function feedbackReadKey(userId=currentUserId()){return FEEDBACK_READ_KEY_PREFIX+encodeURIComponent(text(userId)||'guest')}\n  function localFeedbackReads(userId=currentUserId()){const value=readJson(feedbackReadKey(userId),{});return value&&typeof value==='object'?value:{}}\n  function saveLocalFeedbackReads(value,userId=currentUserId()){return writeJson(feedbackReadKey(userId),value||{})}\n  function withFeedbackReadState(item,reads={}){\n    const row=normalizeFeedback(item),lastReadAt=number(reads[row.id],row.lastReadAt||0);\n    const unreadReplyCount=row.replies.reduce((count,reply)=>count+(number(reply.createdAt,0)>lastReadAt?1:0),0);\n    return {...row,lastReadAt,unreadReplyCount};\n  }\n  function audienceAllows(message,user=currentUser()){\n    const audience=normalizeAudience(message?.audience);\n    if(audience.type==='all')return true;\n    if(audience.type==='roles')return audience.roles.includes(text(user.role));\n    if(audience.type==='users')return audience.users.includes(text(user.username));\n    return false;\n  }\n  function isVisibleMessage(message,{now=Date.now(),user=currentUser(),includeInactive=false}={}){\n    const row=normalizeAnnouncement(message);\n    if(!includeInactive){\n      if(row.status!=='published')return false;\n      const start=row.publishAt||row.publishedAt||0;if(start&&start>now)return false;\n      if(row.expiresAt&&row.expiresAt<=now)return false;\n    }\n    return audienceAllows(row,user);\n  }\n\n  async function submitFeedback(payload={}){\n    const actor=currentUser();\n    const next=normalizeFeedback({...payload,id:uid('feedback'),status:'pending',submittedBy:actor,createdAt:Date.now(),updatedAt:Date.now(),replies:[]});\n    if(!next.title||!next.detail)throw new Error('请填写反馈标题和详细描述。');\n    if(config().mode==='remote')return normalizeFeedback(await remoteRequest(config().endpoints.submitFeedback,{method:'POST',body:next}));\n    const rows=localFeedback();rows.unshift(next);if(!saveLocalFeedback(rows.slice(0,1000)))throw new Error('反馈保存失败。');return clone(next);\n  }\n  async function listMyFeedback(options={}){\n    if(config().mode==='remote'){\n      return (await remoteAllPages(config().endpoints.myFeedback)).map(normalizeFeedback);\n    }\n    const userId=currentUserId(),reads=localFeedbackReads(userId);\n    return localFeedback().filter(item=>item.submittedBy.username===userId).sort((a,b)=>b.createdAt-a.createdAt).map(item=>clone(withFeedbackReadState(item,reads)));\n  }\n  async function unreadFeedbackReplyCount(){return (await listMyFeedback()).reduce((count,item)=>count+Math.max(0,number(item.unreadReplyCount,0)),0)}\n  async function markFeedbackRead(id){\n    id=text(id);if(!id)return false;\n    if(config().mode==='remote'){\n      const path=config().endpoints.markFeedbackRead.replace('{id}',encodeURIComponent(id));\n      await remoteRequest(path,{method:'POST'});return true;\n    }\n    const userId=currentUserId(),feedback=localFeedback().find(item=>item.id===id&&item.submittedBy.username===userId);if(!feedback)return false;\n    const reads=localFeedbackReads(userId),latestReplyAt=feedback.replies.reduce((latest,reply)=>Math.max(latest,number(reply.createdAt,0)),0);\n    reads[id]=Math.max(Date.now(),latestReplyAt);saveLocalFeedbackReads(reads,userId);return true;\n  }\n  async function listFeedback(options={}){\n    let rows;\n    if(config().mode==='remote')rows=(await remoteAllPages(config().endpoints.adminFeedback)).map(normalizeFeedback)\n    else rows=localFeedback();\n    const status=text(options.status),query=text(options.query).toLowerCase(),type=text(options.type);\n    if(status&&status!=='ALL')rows=rows.filter(item=>item.status===status);if(type&&type!=='ALL')rows=rows.filter(item=>item.type===type);\n    if(query)rows=rows.filter(item=>[item.title,item.detail,item.page,item.contact,item.submittedBy.username,item.submittedBy.displayName].some(value=>text(value).toLowerCase().includes(query)));\n    return rows.sort((a,b)=>b.updatedAt-a.updatedAt).map(clone);\n  }\n  async function updateFeedback(id,patch={}){\n    id=text(id);if(!id)throw new Error('反馈 ID 不能为空。');\n    if(config().mode==='remote')return normalizeFeedback(await remoteRequest(config().endpoints.adminFeedback+'/'+encodeURIComponent(id),{method:'PATCH',body:patch}));\n    const rows=localFeedback(),index=rows.findIndex(item=>item.id===id);if(index<0)throw new Error('反馈不存在或已删除。');\n    const status=text(patch.status||rows[index].status);if(status&&!FEEDBACK_STATUSES.includes(status))throw new Error('反馈状态无效。');\n    rows[index]=normalizeFeedback({...rows[index],...patch,status,updatedAt:Date.now()});saveLocalFeedback(rows);return clone(rows[index]);\n  }\n  async function replyFeedback(id,message){\n    id=text(id);message=text(message);if(!message)throw new Error('回复内容不能为空。');\n    if(config().mode==='remote')return normalizeFeedback(await remoteRequest(config().endpoints.adminFeedback+'/'+encodeURIComponent(id)+'/replies',{method:'POST',body:{message}}));\n    const rows=localFeedback(),index=rows.findIndex(item=>item.id===id);if(index<0)throw new Error('反馈不存在或已删除。');\n    const actor=currentUser();rows[index].replies.push({id:uid('reply'),message,actor:actor.displayName||actor.username,createdAt:Date.now()});rows[index].updatedAt=Date.now();\n    if(rows[index].status==='pending')rows[index].status='in_progress';saveLocalFeedback(rows);return clone(rows[index]);\n  }\n\n  async function listAnnouncements(options={}){\n    let rows;\n    if(config().mode==='remote')rows=(await remoteAllPages(config().endpoints.adminMessages)).map(normalizeAnnouncement)\n    else rows=localAnnouncements();\n    const status=text(options.status),query=text(options.query).toLowerCase();\n    if(status&&status!=='ALL')rows=rows.filter(item=>item.status===status);\n    if(query)rows=rows.filter(item=>[item.title,item.body,item.link,item.createdBy].some(value=>text(value).toLowerCase().includes(query)));\n    return rows.sort((a,b)=>b.updatedAt-a.updatedAt).map(clone);\n  }\n  async function saveAnnouncement(payload={}){\n    const now=Date.now(),id=text(payload.id),actor=currentUser();\n    if(config().mode==='remote'){\n      const path=id?config().endpoints.adminMessages+'/'+encodeURIComponent(id):config().endpoints.adminMessages;\n      return normalizeAnnouncement(await remoteRequest(path,{method:id?'PATCH':'POST',body:payload}));\n    }\n    const rows=localAnnouncements();let index=id?rows.findIndex(item=>item.id===id):-1;\n    const base=index>=0?rows[index]:{id:uid('message'),status:'draft',createdAt:now,createdBy:actor.username};\n    const next=normalizeAnnouncement({...base,...payload,id:base.id,updatedAt:now});\n    if(!next.title||!next.body)throw new Error('请填写消息标题和正文。');\n    if(index>=0)rows[index]=next;else rows.unshift(next);saveLocalAnnouncements(rows);return clone(next);\n  }\n  async function publishAnnouncement(id,{publishAt=Date.now()}={}){\n    id=text(id);if(config().mode==='remote')return normalizeAnnouncement(await remoteRequest(config().endpoints.adminMessages+'/'+encodeURIComponent(id)+'/publish',{method:'POST',body:{publishAt}}));\n    const rows=localAnnouncements(),index=rows.findIndex(item=>item.id===id);if(index<0)throw new Error('消息不存在。');\n    rows[index]=normalizeAnnouncement({...rows[index],status:'published',publishAt:number(publishAt,Date.now()),publishedAt:Date.now(),withdrawnAt:0,updatedAt:Date.now()});saveLocalAnnouncements(rows);return clone(rows[index]);\n  }\n  async function withdrawAnnouncement(id){\n    id=text(id);if(config().mode==='remote')return normalizeAnnouncement(await remoteRequest(config().endpoints.adminMessages+'/'+encodeURIComponent(id)+'/withdraw',{method:'POST'}));\n    const rows=localAnnouncements(),index=rows.findIndex(item=>item.id===id);if(index<0)throw new Error('消息不存在。');\n    rows[index]=normalizeAnnouncement({...rows[index],status:'withdrawn',withdrawnAt:Date.now(),updatedAt:Date.now()});saveLocalAnnouncements(rows);return clone(rows[index]);\n  }\n  async function deleteAnnouncement(id){\n    id=text(id);if(config().mode==='remote'){await remoteRequest(config().endpoints.adminMessages+'/'+encodeURIComponent(id),{method:'DELETE'});return true}\n    const rows=localAnnouncements(),target=rows.find(item=>item.id===id);if(!target)return false;if(target.status==='published')throw new Error('已发布消息请先撤回，不能直接删除。');\n    saveLocalAnnouncements(rows.filter(item=>item.id!==id));return true;\n  }\n  async function listUserMessages(options={}){\n    if(config().mode==='remote')return (await remoteAllPages(config().endpoints.messages)).map(item=>({...normalizeAnnouncement(item),read:!!item.read,readAt:number(item.readAt,0)}))\n    const user=currentUser(),reads=localReads(user.username);\n    return localAnnouncements().filter(item=>isVisibleMessage(item,{user})).sort((a,b)=>(b.publishAt||b.publishedAt||b.createdAt)-(a.publishAt||a.publishedAt||a.createdAt)).map(item=>({...clone(item),read:!!reads[item.id],readAt:number(reads[item.id],0)}));\n  }\n  async function unreadCount(){return (await listUserMessages()).filter(item=>!item.read).length}\n  async function unreadSummary(){\n    if(config().mode==='remote'){\n      const summary=await remoteRequest(config().endpoints.unreadSummary);\n      const messages=Math.max(0,number(summary?.messages,0)),feedbackReplies=Math.max(0,number(summary?.feedbackReplies,0));\n      return {messages,feedbackReplies,total:messages+feedbackReplies};\n    }\n    const [messages,feedbackReplies]=await Promise.all([unreadCount(),unreadFeedbackReplyCount()]);\n    return {messages,feedbackReplies,total:messages+feedbackReplies};\n  }\n  async function markMessageRead(id){\n    id=text(id);if(!id)return false;\n    if(config().mode==='remote'){const path=config().endpoints.markMessageRead.replace('{id}',encodeURIComponent(id));await remoteRequest(path,{method:'POST'});return true}\n    const userId=currentUserId(),reads=localReads(userId);reads[id]=Date.now();saveLocalReads(reads,userId);return true;\n  }\n  async function markAllMessagesRead(){\n    if(config().mode==='remote'){await remoteRequest(config().endpoints.markAllRead,{method:'POST'});return true}\n    const userId=currentUserId(),reads=localReads(userId),messages=await listUserMessages();messages.forEach(item=>{reads[item.id]=Date.now()});saveLocalReads(reads,userId);return true;\n  }\n  function messageStats(id){\n    id=text(id);const keys=[];try{for(let i=0;i<(global.localStorage?.length||0);i++){const key=global.localStorage.key(i);if(key?.startsWith(READ_KEY_PREFIX))keys.push(key)}}catch(error){}\n    let readCount=0;keys.forEach(key=>{const map=readJson(key,{});if(map&&map[id])readCount+=1});return {readCount};\n  }\n\n  const api=Object.freeze({\n    feedbackStorageKey:FEEDBACK_KEY,feedbackReadStoragePrefix:FEEDBACK_READ_KEY_PREFIX,announcementStorageKey:ANNOUNCEMENT_KEY,readStoragePrefix:READ_KEY_PREFIX,eventName:EVENT_NAME,\n    feedbackStatuses:FEEDBACK_STATUSES,messageStatuses:MESSAGE_STATUSES,config,currentUser,currentUserId,\n    submitFeedback,listMyFeedback,listFeedback,updateFeedback,replyFeedback,unreadFeedbackReplyCount,markFeedbackRead,\n    listAnnouncements,saveAnnouncement,publishAnnouncement,withdrawAnnouncement,deleteAnnouncement,\n    listUserMessages,unreadCount,unreadSummary,markMessageRead,markAllMessagesRead,messageStats,isVisibleMessage,audienceAllows\n  });\n  global.KGEngagementRepository=api;\n  if(typeof module!=='undefined'&&module.exports)module.exports=api;\n})(typeof window!=='undefined'?window:globalThis);\n//# sourceURL=src/101-engagement-repository.js"],["src/102-help-content.js","'use strict';\n(function(global){\n  const docs=[\n    {\n      id:'home',title:'图谱首页',href:'index.html',keywords:['首页','图谱','卡牌','连线','画布','框选','右键','拖动'],summary:'创建、整理和浏览个人知识图谱。',\n      sections:[\n        {title:'画布与视图',body:'左键用于选择和编辑；在画布空白处直接拖出选框，无需按 Shift。滚轮缩放，右键拖动或空格键配合拖动可以平移画布。右键轻点会打开画布或图元快捷菜单。'},\n        {title:'框选与多选',body:'选框可同时命中知识节点、文本框和关系线。混合框选后，通过悬浮栏中的“多选（N）”只保留某一类型；纯关系线框选只显示关系线工具栏。已有选框时，可直接在选框外重新框选，不必先取消。'},\n        {title:'整体移动',body:'框选多个可移动图元后，按住选区或任意已选卡牌即可整体移动。拖动期间关系线自动进入轻量模式：只绘制简单主线，临时隐藏箭头、描边、控制点、命中层和辅助线，松开后恢复完整效果。'},\n        {title:'卡牌与关系线',body:'单击卡牌查看详情，再次单击已选卡牌可原位编辑。使用卡牌连接手柄或工具栏“连线”建立关系；关系线可批量修改颜色、线型、粗细、路径、箭头和文字。'},\n        {title:'文件与保存',body:'图谱会自动保存到当前文件。使用文件页签切换图谱，定期导出学习包 ZIP 作为离线备份；导入和清空会修改数据，需要登录权限。'},\n        {title:'大图性能',body:'关系较多时系统会采用局部关系线、逐帧合并更新和轻量拖动策略。可在视图设置中关闭阴影或动画；拖动结束后再进行完整几何与交互层恢复。'}\n      ]\n    },\n    {\n      id:'practice',title:'做题模式',href:'practice-mode.html',keywords:['做题','挑战','学霸','复仇','倒计时','经验值','试卷','练习','解析','学习记录'],summary:'使用已发布试卷进行挑战、学霸或按卷复习。',\n      sections:[\n        {title:'试卷来源',body:'做题大厅只显示当前已发布、且开放了做题模式的试卷。教师更新或下架版本后，大厅会同步变化。'},\n        {title:'练习数量',body:'可按试卷题量选择 10、20、60 或 180 道题，并选择按顺序或随机练习。'},\n        {title:'挑战模式',body:'初始生命随题量动态计算（约为题数的 30%，最低 3 点）。答错扣 1 点生命；生命归零判定本次挑战失败，但不会中断试卷，你可以继续完成剩余题目。结算时分别展示试卷完成结果和挑战结果。'},\n        {title:'学霸模式',body:'共享 60 秒时间池：答对 +20 秒（上限 60），答错 -20 秒并扣 1 点生命；连续答对 5 题恢复 1 点生命（不超过初始上限）。生命归零立即结束，判定学霸挑战失败。'},\n        {title:'复仇模式',body:'集中处理你的真实错题。再次答错会先提示知识点补救；完全答对并通过后续验证即标记为彻底掌握。支持底部按钮或左右滑动切换题目。'},\n        {title:'练习模式（按卷复习）',body:'入口在学习记录中：打开“学习记录”，点击某份练习过的试卷即可直接进入该卷练习。练习模式没有时间与生命限制，答题后立即显示正确答案与解析；可用“自动解析”开关控制是否自动展示，底部按钮可上一题/下一题，移动端支持左右滑动切题。同一试卷重复练习不会新增记录，只更新次数、最近时间和最近成绩。'},\n        {title:'语言切换',body:'做题界面顶部有语言按钮，点击在中文、英文、双语对照之间循环切换，立即生效，不影响作答与判题。'},\n        {title:'经验值',body:'大厅左侧（窄屏为右下角 XP 入口）显示做题经验：累计经验永久保存；本周经验按学习周（周日 19:00 至下周日 19:00）统计并自动清零；折线图展示最近 7 天每日经验，帮助判断学习状态。经验仅统计做题模式产生部分。'},\n        {title:'退出与结算',body:'挑战与学霸模式均不可暂停。结算显示正确率、总耗时、经验值和模式判定；中途退出会按当前完成情况结束本次练习。'}\n      ]\n    },\n    {\n      id:'multi-question',title:'多题画布',href:'question-workspace.html',keywords:['多题画布','试卷','题目卡','归纳','框选','高亮'],summary:'把同一发布试卷中的多道题放入画布进行整理。',\n      sections:[\n        {title:'题目来源',body:'只读取当前已发布、且开放了“多题画布”的固定版本。后续的内容调整不会改变已经发布的冻结题目。'},\n        {title:'框选与悬浮栏',body:'框选可命中题目卡、归纳卡、文本元素和关系线。纯关系线仅显示关系线工具栏；混合选择可用“多选（N）”筛选类型。选区可直接拖动，右键平移和滚轮缩放不会清除选择。'},\n        {title:'拖动性能',body:'整体移动多张卡片时只显示简单关系线，临时隐藏描边、中心反馈线、标签、命中层和箭头，并将连续几何更新合并到动画帧。'},\n        {title:'归纳与练习',body:'归纳卡练习控件分为左右两段：右侧星级在★、★★、★★★之间循环；左侧“练习”按当前星级出题。教师预设归纳只读，复制后可编辑为“我的归纳”。'},\n        {title:'临时文字高亮',body:'中文题干和选项高亮只在当前页面会话中存在。再次选择相同颜色会取消高亮；选择其他颜色只改色。英文内容不会因中文高亮而消失。'},\n        {title:'学习模式',body:'多题画布用于聚合题目并归纳原则；需要回忆或刷题时，请从登录后的学习入口选择深度回忆或刷题。'}\n      ]\n    },\n    {\n      id:'deep-recall',title:'深度回忆',href:'knowledge-recall.html',keywords:['深度回忆','回忆','联想','关键词','知识图谱','进度'],summary:'围绕题目关键词展开科目级知识联想。',\n      sections:[\n        {title:'题目来源',body:'只读取当前已发布、且开放了“深度回忆”的试卷版本，内容以发布时的冻结版本为准。'},\n        {title:'关键词与联想入口',body:'题目关键词负责定义可点击文字；知识联想入口负责把关键词绑定到科目级联想库节点，点击后展开知识卡片。'},\n        {title:'画布操作',body:'左键点击关键词展开知识节点；右键可从空白、题目卡或知识卡范围内拖动画布。浏览器默认右键菜单已禁用，右键轻点显示统一画布菜单。'},\n        {title:'进度保存',body:'登录用户的探索节点、连接线、激活关键词、自定义节点和视口会自动保存。进度按用户、试卷发布版本和题目隔离。'}\n      ]\n    }\n  ];\n  global.KGHelpContent=Object.freeze({docs:Object.freeze(docs.map(doc=>Object.freeze({...doc,sections:Object.freeze(doc.sections.map(section=>Object.freeze(section)))}))) });\n  if(typeof module!=='undefined'&&module.exports)module.exports=global.KGHelpContent;\n})(typeof window!=='undefined'?window:globalThis);\n//# sourceURL=src/102-help-content.js"],["src/103-support-center.js","'use strict';\n(function(global){\n  const $=id=>document.getElementById(id);\n  const Repository=()=>global.KGEngagementRepository;\n  let shell,trigger,popover,badge,feedbackMenuBadge,messageMenuBadge,refreshTimer=0,toastTimer=0,dialogReturnFocus=null;\n  const FOCUSABLE='button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex=\"-1\"])';\n  const MAX_ATTACHMENT_BYTES=160*1024;\n  function escapeHtml(value){return String(value??'').replace(/[&<>'\"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[char]))}\n  function fmtTime(value){try{return new Date(Number(value||0)).toLocaleString('zh-CN',{hour12:false})}catch(error){return '—'}}\n  function safeHref(value){const href=String(value||'').trim();if(!href)return '';if(/^(https?:\\/\\/|\\/?[\\w.-]+(?:\\/[^\\s]*)?|[\\w.-]+\\.html(?:[?#][^\\s]*)?)$/i.test(href))return href;return ''}\n  function toast(message,error=false){let el=$('engagementToast');if(!el){el=document.createElement('div');el.id='engagementToast';el.className='engagement-toast';document.body.appendChild(el)}el.textContent=message;el.classList.toggle('error',!!error);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}\n  function closePopover({focus=false}={}){if(!popover||!trigger)return;popover.hidden=true;trigger.setAttribute('aria-expanded','false');if(focus)trigger.focus()}\n  function openPopover(){if(!popover||!trigger)return;popover.hidden=false;trigger.setAttribute('aria-expanded','true');refreshUnread();requestAnimationFrame(()=>popover.querySelector('button')?.focus())}\n  function togglePopover(){if(popover?.hidden)openPopover();else closePopover()}\n  function ensureShell(){\n    shell=$('supportCenterShell');\n    if(shell)return shell;\n    const toolbar=document.querySelector('.canvas-toolbar-right,.lp-top-actions,.practice-header-actions,.fm-top-actions');if(!toolbar)return null;\n    shell=document.createElement('div');shell.id='supportCenterShell';shell.className='support-center-shell';\n    shell.innerHTML=`<button class=\"support-center-trigger\" id=\"supportCenterBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"supportCenterMenu\" title=\"帮助、反馈与消息\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.8 9a2.35 2.35 0 1 1 3.5 2.05c-.82.45-1.3.93-1.3 1.95\"/><path d=\"M12 17h.01\"/></svg><span class=\"support-center-badge\" id=\"supportCenterBadge\" hidden>0</span></button><div class=\"support-center-popover\" id=\"supportCenterMenu\" role=\"menu\" hidden><button type=\"button\" role=\"menuitem\" data-support-action=\"help\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5Z\"/><path d=\"M4 5.5v16\"/></svg><span>帮助中心</span></button><button type=\"button\" role=\"menuitem\" data-support-action=\"contact\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M20 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h4.5l2.2 3 3.6-3H20a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2Z\"/><path d=\"M8 11h8M8 14h5M6 8h12\"/><circle cx=\"17\" cy=\"9.8\" r=\".7\"/><path d=\"M15 17c0-1.2-2.2-2-5-2s-5 .8-5 2\"/></svg><span>联系我们</span></button><button type=\"button\" role=\"menuitem\" data-support-action=\"feedback\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 5h16v12H8l-4 4Z\"/><path d=\"M8 9h8M8 13h5\"/></svg><span>需求反馈</span><b class=\"menu-badge\" id=\"supportFeedbackMenuBadge\" hidden>0</b></button><button type=\"button\" role=\"menuitem\" data-support-action=\"messages\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 7h18s-3 0-3-7\"/><path d=\"M10 19h4\"/></svg><span>消息</span><b class=\"menu-badge\" id=\"supportMessageMenuBadge\" hidden>0</b></button></div>`;\n    const account=document.getElementById('accountMenuShell');if(account&&account.parentNode===toolbar)account.insertAdjacentElement('afterend',shell);else toolbar.appendChild(shell);\n    return shell;\n  }\n  function ensureDialog(){\n    let backdrop=$('engagementDialogBackdrop');if(backdrop)return backdrop;\n    backdrop=document.createElement('div');backdrop.id='engagementDialogBackdrop';backdrop.className='engagement-backdrop';backdrop.hidden=true;\n    backdrop.innerHTML=`<section class=\"engagement-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"engagementDialogTitle\"><header><div><h2 id=\"engagementDialogTitle\">需求反馈</h2><p id=\"engagementDialogSubtitle\"></p></div><button class=\"engagement-close\" id=\"engagementDialogClose\" type=\"button\" aria-label=\"关闭\" title=\"关闭\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg></button></header><div class=\"engagement-body\" id=\"engagementDialogBody\"></div></section>`;\n    document.body.appendChild(backdrop);$('engagementDialogClose').addEventListener('click',closeDialog);backdrop.addEventListener('click',event=>{if(event.target===backdrop)closeDialog()});return backdrop;\n  }\n  function visibleFocusable(root){return [...root.querySelectorAll(FOCUSABLE)].filter(item=>!item.hidden&&item.getClientRects().length>0)}\n  function trapDialogFocus(event){\n    const backdrop=$('engagementDialogBackdrop');if(event.key!=='Tab'||!backdrop||backdrop.hidden)return;\n    const items=visibleFocusable(backdrop);if(!items.length){event.preventDefault();return}\n    const first=items[0],last=items[items.length-1];\n    if(!backdrop.contains(document.activeElement)){event.preventDefault();(event.shiftKey?last:first).focus()}\n    else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}\n    else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}\n  }\n  function closeDialog(){const dialog=$('engagementDialogBackdrop');if(!dialog||dialog.hidden)return;dialog.hidden=true;document.body.classList.remove('engagement-dialog-open');const target=dialogReturnFocus;dialogReturnFocus=null;requestAnimationFrame(()=>target?.focus?.())}\n  function openDialog(title,subtitle=''){const dialog=ensureDialog();dialogReturnFocus=trigger||document.activeElement;$('engagementDialogTitle').textContent=title;$('engagementDialogSubtitle').textContent=subtitle;$('engagementDialogBody').innerHTML='';dialog.hidden=false;document.body.classList.add('engagement-dialog-open');requestAnimationFrame(()=>$('engagementDialogClose')?.focus());return $('engagementDialogBody')}\n  function statusLabel(status){return ({pending:'待处理',in_progress:'处理中',resolved:'已解决',closed:'已关闭'}[status]||status||'待处理')}\n  async function filePayload(file){\n    if(!file)return null;if(file.size>MAX_ATTACHMENT_BYTES)throw new Error('截图不能超过 160KB。');\n    const allowed=/^image\\/(png|jpeg|webp|gif)$/i.test(file.type||'');if(!allowed)throw new Error('截图仅支持 PNG、JPG、WebP 或 GIF。');\n    const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('截图读取失败。'));reader.readAsDataURL(file)});\n    return {name:file.name,type:file.type,size:file.size,dataUrl};\n  }\n  function renderFeedbackForm(body){\n    body.innerHTML=`<div class=\"engagement-tabs\"><button type=\"button\" class=\"active\" data-feedback-tab=\"new\">提交反馈</button><button type=\"button\" data-feedback-tab=\"mine\"><span>我的反馈</span><b class=\"feedback-tab-badge\" id=\"feedbackTabBadge\" hidden>0</b></button></div><section id=\"feedbackTabContent\"></section>`;\n    body.querySelectorAll('[data-feedback-tab]').forEach(button=>button.addEventListener('click',()=>{body.querySelectorAll('[data-feedback-tab]').forEach(item=>item.classList.toggle('active',item===button));button.dataset.feedbackTab==='mine'?renderMyFeedback(body):renderNewFeedback(body)}));\n    renderNewFeedback(body);\n  }\n  function renderNewFeedback(body){\n    const content=body.querySelector('#feedbackTabContent');if(!content)return;\n    content.innerHTML=`<form class=\"engagement-form\" id=\"feedbackForm\" novalidate><div class=\"engagement-form-row\"><label>反馈类型<select id=\"feedbackType\"><option value=\"suggestion\">功能建议</option><option value=\"bug\">问题反馈</option><option value=\"content\">内容问题</option><option value=\"other\">其他</option></select></label><label>联系方式（选填）<input id=\"feedbackContact\" maxlength=\"120\" placeholder=\"邮箱或手机号\"/></label></div><label>标题<input id=\"feedbackTitle\" maxlength=\"100\" aria-describedby=\"feedbackFormError\" placeholder=\"请简要说明问题或建议\"/></label><label>详细描述<textarea id=\"feedbackDetail\" maxlength=\"4000\" aria-describedby=\"feedbackFormError\" placeholder=\"请描述发生了什么、期望结果以及复现步骤\"></textarea></label><label>截图（选填，最大 160KB）<input id=\"feedbackAttachment\" type=\"file\" accept=\"image/png,image/jpeg,image/webp,image/gif\"/></label><div class=\"engagement-form-error\" id=\"feedbackFormError\" role=\"alert\" hidden></div><div class=\"engagement-note\">将自动记录当前页面、账号角色和应用版本，不会自动提交图谱或题目内容。</div><button class=\"engagement-primary\" type=\"submit\">提交反馈</button></form>`;\n    $('feedbackForm').addEventListener('submit',async event=>{\n      event.preventDefault();const title=$('feedbackTitle').value.trim(),detail=$('feedbackDetail').value.trim(),errorBox=$('feedbackFormError');\n      if(!title||!detail){errorBox.textContent='请填写反馈标题和详细描述。';errorBox.hidden=false;(title?$('feedbackDetail'):$('feedbackTitle')).focus();return}\n      errorBox.hidden=true;const button=event.submitter||$('feedbackForm').querySelector('[type=\"submit\"]');button.disabled=true;\n      try{\n        const attachment=await filePayload($('feedbackAttachment').files?.[0]);\n        await Repository().submitFeedback({type:$('feedbackType').value,title,detail,contact:$('feedbackContact').value,page:location.pathname.split('/').pop()||'index.html',appVersion:document.documentElement.dataset.release||'',attachment});\n        toast('反馈已提交，谢谢你的建议！');$('feedbackForm').reset();\n      }catch(error){toast(error.message||'反馈提交失败。',true)}finally{button.disabled=false}\n    });\n  }\n  async function renderMyFeedback(body){\n    const content=body.querySelector('#feedbackTabContent');if(!content)return;content.innerHTML='<div class=\"engagement-empty\">正在读取反馈…</div>';\n    try{\n      const rows=await Repository().listMyFeedback();\n      const unreadRows=rows.filter(item=>Number(item.unreadReplyCount||0)>0);\n      content.innerHTML=rows.length?`<div class=\"my-feedback-list\">${rows.map(item=>`<article class=\"my-feedback-card ${Number(item.unreadReplyCount||0)>0?'unread-reply':''}\"><header><div><h3>${escapeHtml(item.title)}</h3><span class=\"feedback-status ${escapeHtml(item.status)}\">${escapeHtml(statusLabel(item.status))}</span>${Number(item.unreadReplyCount||0)>0?`<span class=\"feedback-reply-badge\">管理员新回复 ${escapeHtml(item.unreadReplyCount)}</span>`:''}</div><time>${escapeHtml(fmtTime(item.updatedAt))}</time></header><p>${escapeHtml(item.detail)}</p>${item.replies?.length?`<div class=\"feedback-replies\"><strong>处理回复</strong>${item.replies.map(reply=>`<article><b>${escapeHtml(reply.actor)}</b> · ${escapeHtml(fmtTime(reply.createdAt))}<div>${escapeHtml(reply.message)}</div></article>`).join('')}</div>`:''}</article>`).join('')}</div>`:'<div class=\"engagement-empty\">还没有提交过反馈。</div>';\n      if(unreadRows.length){await Promise.all(unreadRows.map(item=>Repository().markFeedbackRead(item.id)));refreshUnread()}\n    }catch(error){content.innerHTML=`<div class=\"engagement-empty\">${escapeHtml(error.message||'反馈读取失败。')}</div>`}\n  }\n  function openFeedback(){closePopover();const body=openDialog('需求反馈','提交问题、建议或内容反馈，并查看处理进度。');renderFeedbackForm(body);refreshUnread()}\n  function openContact(){closePopover();const body=openDialog('联系我们','如需帮助可扫码添加客服。');body.innerHTML=`<div class=\\\"contact-service-card\\\"><p class=\\\"contact-service-title\\\">扫码添加客服</p><p class=\\\"contact-service-subtitle\\\">账号问题、课程问题、学习问题，均可在对话中说明。</p><img class=\\\"contact-service-qrcode\\\" src=\\\"assets/客服二维码/1.jpg\\\" alt=\\\"客服二维码\\\"/><p class=\\\"contact-service-tip\\\">添加后请备注你的用户名（例如：学校/课程），便于我们快速处理。</p></div>`}\n  async function openMessages(){\n    closePopover();const body=openDialog('消息','查看管理员和运营人员发布的通知。');body.innerHTML='<div class=\"engagement-empty\">正在读取消息…</div>';\n    try{\n      const rows=await Repository().listUserMessages();\n      body.innerHTML=`<div class=\"message-toolbar\"><button type=\"button\" id=\"messageMarkAllBtn\" ${rows.some(item=>!item.read)?'':'disabled'}>全部标为已读</button></div>${rows.length?`<div class=\"message-list\">${rows.map(item=>{const href=safeHref(item.link);return `<article class=\"message-card ${item.read?'':'unread'}\" data-message-id=\"${escapeHtml(item.id)}\"><header><h3>${escapeHtml(item.title)}</h3><time>${escapeHtml(fmtTime(item.publishAt||item.publishedAt||item.createdAt))}</time></header><p>${escapeHtml(item.body)}</p><div>${href?`<button type=\"button\" data-message-link=\"${escapeHtml(href)}\">查看详情</button>`:''}${item.read?'':`<button type=\"button\" data-message-read=\"${escapeHtml(item.id)}\">标为已读</button>`}</div></article>`}).join('')}</div>`:'<div class=\"engagement-empty\">目前没有消息。</div>'}`;\n      body.querySelectorAll('[data-message-read]').forEach(button=>button.addEventListener('click',async()=>{await Repository().markMessageRead(button.dataset.messageRead);button.closest('.message-card')?.classList.remove('unread');button.remove();refreshUnread()}));\n      body.querySelectorAll('[data-message-link]').forEach(button=>button.addEventListener('click',async()=>{const card=button.closest('[data-message-id]');if(card)await Repository().markMessageRead(card.dataset.messageId);location.href=button.dataset.messageLink}));\n      $('messageMarkAllBtn')?.addEventListener('click',async()=>{await Repository().markAllMessagesRead();body.querySelectorAll('.message-card').forEach(card=>card.classList.remove('unread'));body.querySelectorAll('[data-message-read]').forEach(button=>button.remove());$('messageMarkAllBtn').disabled=true;refreshUnread()});\n    }catch(error){body.innerHTML=`<div class=\"engagement-empty\">${escapeHtml(error.message||'消息读取失败。')}</div>`}\n  }\n  function openHelp(){closePopover();const returnTo=(location.pathname.split('/').pop()||'index.html')+location.search+location.hash;location.href='help-center.html?returnTo='+encodeURIComponent(returnTo)}\n  function applyBadge(element,count){if(!element)return;const safe=Math.max(0,Number(count||0));element.textContent=safe>99?'99+':String(safe);element.hidden=safe<=0}\n  async function refreshUnread(){\n    if(!Repository()||!badge)return;\n    try{\n      const summary=Repository().unreadSummary?await Repository().unreadSummary():{messages:await Repository().unreadCount(),feedbackReplies:0};\n      summary.total=Number(summary.total??(Number(summary.messages||0)+Number(summary.feedbackReplies||0)));\n      applyBadge(badge,summary.total);applyBadge(messageMenuBadge,summary.messages);applyBadge(feedbackMenuBadge,summary.feedbackReplies);applyBadge($('feedbackTabBadge'),summary.feedbackReplies);\n      if(trigger)trigger.title=summary.total>0?`帮助、反馈与消息（${summary.total} 条未读）`:'帮助、反馈与消息';\n    }catch(error){applyBadge(badge,0);applyBadge(messageMenuBadge,0);applyBadge(feedbackMenuBadge,0);applyBadge($('feedbackTabBadge'),0)}\n  }\n  function onKeydown(event){\n    trapDialogFocus(event);\n    if(event.key==='Escape'){const dialog=$('engagementDialogBackdrop');if(dialog&&!dialog.hidden)closeDialog();else closePopover({focus:true});return}\n    if(!popover||popover.hidden)return;const items=[...popover.querySelectorAll('[role=\"menuitem\"]')];const index=items.indexOf(document.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const step=event.key==='ArrowDown'?1:-1;items[(Math.max(index,0)+step+items.length)%items.length]?.focus()}\n  }\n  function init(){\n    if(!Repository())return;if(!ensureShell())return;trigger=$('supportCenterBtn');popover=$('supportCenterMenu');badge=$('supportCenterBadge');feedbackMenuBadge=$('supportFeedbackMenuBadge');messageMenuBadge=$('supportMessageMenuBadge');if(shell.dataset.bound==='1')return;shell.dataset.bound='1';\n    trigger.addEventListener('click',event=>{event.stopPropagation();togglePopover()});popover.querySelector('[data-support-action=\"help\"]').addEventListener('click',openHelp);popover.querySelector('[data-support-action=\"contact\"]').addEventListener('click',openContact);popover.querySelector('[data-support-action=\"feedback\"]').addEventListener('click',openFeedback);popover.querySelector('[data-support-action=\"messages\"]').addEventListener('click',openMessages);\n    document.addEventListener('click',event=>{if(!shell.contains(event.target))closePopover()});document.addEventListener('keydown',onKeydown);global.addEventListener('blur',()=>closePopover());global.addEventListener('resize',()=>closePopover());\n    global.addEventListener(Repository().eventName,refreshUnread);global.addEventListener('storage',event=>{if(!event.key||event.key===Repository().feedbackStorageKey||event.key===Repository().announcementStorageKey||event.key?.startsWith(Repository().readStoragePrefix)||event.key?.startsWith(Repository().feedbackReadStoragePrefix))refreshUnread()});global.addEventListener('kg-auth-session-change',refreshUnread);\n    refreshUnread();refreshTimer=global.setInterval(refreshUnread,60000);\n  }\n  global.KGSupportCenter=Object.freeze({openFeedback,openMessages,refreshUnread,closePopover});\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();\n})(window);\n//# sourceURL=src/103-support-center.js"]]);
